#include <iostream>
#include <vector>
#include <cstdint>
#include <cuda_runtime.h>
using namespace std;

__global__ void hammingKernel(const uint64_t *d, int N, int L, unsigned long long *result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && j < N && i < j) {
        unsigned long long localSum = 0;
        for (int w = 0; w < L; ++w) {
            uint64_t x = d[(size_t)i * L + w] ^ d[(size_t)j * L + w];
            localSum += __popcll(x);
        }
        atomicAdd(result, localSum);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;
    size_t size = (size_t)N * L;
    vector<uint64_t> d_host(size);
    for(int i = 0; i < N; i++){
        for(int w = 0; w < L; w++){
            d_host[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    uint64_t *d_dev;
    cudaMalloc(&d_dev, size * sizeof(uint64_t));
    cudaMemcpy(d_dev, d_host.data(), size * sizeof(uint64_t), cudaMemcpyHostToDevice);

    unsigned long long *result_dev;
    cudaMalloc(&result_dev, sizeof(unsigned long long));
    cudaMemset(result_dev, 0, sizeof(unsigned long long));

    dim3 blockDim(16, 16);
    dim3 gridDim((N + blockDim.x - 1) / blockDim.x, (N + blockDim.y - 1) / blockDim.y);
    hammingKernel<<<gridDim, blockDim>>>(d_dev, N, L, result_dev);
    cudaDeviceSynchronize();

    unsigned long long s;
    cudaMemcpy(&s, result_dev, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cout << s << "\n";

    cudaFree(d_dev);
    cudaFree(result_dev);
    return 0;
}

