#include <iostream>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void gameOfLifeKernel(const uint8_t *A, uint8_t *B, int H, int W) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(i >= 1 && i < H - 1 && j >= 1 && j < W - 1){
        int idx = i * W + j;
        int c = 0;
        c += A[(i - 1) * W + (j - 1)];
        c += A[(i - 1) * W + j];
        c += A[(i - 1) * W + (j + 1)];
        c += A[i * W + (j - 1)];
        c += A[i * W + (j + 1)];
        c += A[(i + 1) * W + (j - 1)];
        c += A[(i + 1) * W + j];
        c += A[(i + 1) * W + (j + 1)];
        B[idx] = A[idx] ? ((c == 2) || (c == 3)) : (c == 3);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    vector<uint8_t> hostA(H * W), hostB(H * W);
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            hostA[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
        }
    }

    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, H * W * sizeof(uint8_t));
    cudaMalloc(&d_B, H * W * sizeof(uint8_t));
    cudaMemcpy(d_A, hostA.data(), H * W * sizeof(uint8_t), cudaMemcpyHostToDevice);

    dim3 blockSize(16, 16);
    dim3 gridSize((W + blockSize.x - 1) / blockSize.x, (H + blockSize.y - 1) / blockSize.y);

    for(int t = 0; t < T; t++){
        gameOfLifeKernel<<<gridSize, blockSize>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        uint8_t *temp = d_A; d_A = d_B; d_B = temp;
    }

    cudaMemcpy(hostA.data(), d_A, H * W * sizeof(uint8_t), cudaMemcpyDeviceToHost);
    long long s = 0;
    for(auto v : hostA) s += v;
    cout << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

