#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

__global__ void compute_d_kernel(const int* a, const int* d, int a_val, int i, int* d_i)
{
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i){
        if(a[j] < a_val){
            int candidate = d[j] + 1;
            atomicMax(d_i, candidate);
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N; 
    cin >> N;
    vector<int> a_host(N), d_host(N,1);
    for(int i = 0; i < N; i++){
        a_host[i] = (int)(((long long)i*48271 + ((i>>1)*163LL) + 7) % 100000);
    }

    int best = 0;

    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));

    cudaMemcpy(d_a, a_host.data(), N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, d_host.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    best = 1; // d[0] is 1

    for (int i = 1; i < N; i++){
        int init_val = 1;
        int *d_d_i;
        cudaMalloc((void**)&d_d_i, sizeof(int));
        cudaMemcpy(d_d_i, &init_val, sizeof(int), cudaMemcpyHostToDevice);

        int threads = 256;
        int blocks = (i + threads - 1) / threads;
        compute_d_kernel<<<blocks, threads>>>(d_a, d_d, a_host[i], i, d_d_i);
        cudaDeviceSynchronize();

        int d_val;
        cudaMemcpy(&d_val, d_d_i, sizeof(int), cudaMemcpyDeviceToHost);
        cudaFree(d_d_i);

        cudaMemcpy(d_d + i, &d_val, sizeof(int), cudaMemcpyHostToDevice);
        best = max(best, d_val);
    }

    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    return 0;
}

