#include <iostream>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void update_d(int i, const int *a, int *d) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i) {
        if(a[j] < a[i]) {
            int candidate = d[j] + 1;
            atomicMax(&d[i], candidate);
        }
    }
}

__global__ void reduce_max(const int *d, int n, int *result) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int max_val = 0;
    if(i < n)
        max_val = d[i];
    sdata[tid] = max_val;
    __syncthreads();
    for(int s = blockDim.x / 2; s > 0; s >>= 1) {
        if(tid < s && (tid + s) < blockDim.x) {
            sdata[tid] = sdata[tid] > sdata[tid + s] ? sdata[tid] : sdata[tid + s];
        }
        __syncthreads();
    }
    if(tid == 0)
        atomicMax(result, sdata[0]);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N; 
    cin >> N;
    vector<int> h_a(N), h_d(N, 1);
    for(int i = 0; i < N; i++){
        long long t = (long long)i * 48271 + (i >> 1) * 163 + 7;
        h_a[i] = t % 100000;
    }

    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));
    cudaMemcpy(d_a, h_a.data(), N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    int blockSize = 256;
    for (int i = 1; i < N; i++){
        int gridSize = (i + blockSize - 1) / blockSize;
        update_d<<<gridSize, blockSize>>>(i, d_a, d_d);
        cudaDeviceSynchronize();
    }

    int *d_result;
    cudaMalloc(&d_result, sizeof(int));
    cudaMemset(d_result, 0, sizeof(int));
    int gridSize_reduce = (N + blockSize - 1) / blockSize;
    reduce_max<<<gridSize_reduce, blockSize, blockSize * sizeof(int)>>>(d_d, N, d_result);
    int best;
    cudaMemcpy(&best, d_result, sizeof(int), cudaMemcpyDeviceToHost);
    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

