#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <iostream>
using namespace std;

__global__ void init_d(uint64_t* d, int N, int L) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int w = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && w < L) {
        d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void compare_pairs(const uint64_t* d, int N, int L, unsigned long long* s) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && j < N && i < j) {
        unsigned long long local_sum = 0;
        for (int w = 0; w < L; w++) {
            local_sum += __popcll(d[(size_t)i * L + w] ^ d[(size_t)j * L + w]);
        }
        atomicAdd(s, local_sum);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;

    size_t d_size = (size_t)N * L * sizeof(uint64_t);
    uint64_t *d_d;
    cudaMalloc(&d_d, d_size);

    dim3 blockInit(16, 16);
    dim3 gridInit((N + blockInit.x - 1) / blockInit.x, (L + blockInit.y - 1) / blockInit.y);
    init_d<<<gridInit, blockInit>>>(d_d, N, L);
    cudaDeviceSynchronize();

    unsigned long long *d_s;
    cudaMalloc(&d_s, sizeof(unsigned long long));
    cudaMemset(d_s, 0, sizeof(unsigned long long));

    dim3 blockPairs(16, 16);
    dim3 gridPairs((N + blockPairs.x - 1) / blockPairs.x, (N + blockPairs.y - 1) / blockPairs.y);
    compare_pairs<<<gridPairs, blockPairs>>>(d_d, N, L, d_s);
    cudaDeviceSynchronize();

    unsigned long long s;
    cudaMemcpy(&s, d_s, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cout << s << "\n";

    cudaFree(d_d);
    cudaFree(d_s);
    return 0;
}

