#include <iostream>
#include <cuda_runtime.h>
using namespace std;

__global__ void compute_dp(int i, const int *a, int *d) {
    int tid = threadIdx.x + blockDim.x * blockIdx.x;
    int stride = blockDim.x * gridDim.x;
    int local_max = 1;
    for (int j = tid; j < i; j += stride) {
        if(a[j] < a[i]){
            local_max = local_max > (d[j] + 1) ? local_max : (d[j] + 1);
        }
    }
    __shared__ int sdata[1024];
    int lane = threadIdx.x;
    sdata[lane] = local_max;
    __syncthreads();
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if(lane < s) {
            int other = sdata[lane+s];
            if(other > sdata[lane])
                sdata[lane] = other;
        }
        __syncthreads();
    }
    if(threadIdx.x == 0) {
        atomicMax(&d[i], sdata[0]);
    }
}

__global__ void reduce_max(int *d, int N, int *res) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * (blockDim.x * 2) + tid;
    int max_val = 0;
    if(i < N) max_val = d[i];
    if(i + blockDim.x < N) {
        int temp = d[i + blockDim.x];
        if(temp > max_val)
            max_val = temp;
    }
    sdata[tid] = max_val;
    __syncthreads();
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if(tid < s){
            int other = sdata[tid+s];
            if(other > sdata[tid])
                sdata[tid] = other;
        }
        __syncthreads();
    }
    if(tid == 0) {
        atomicMax(res, sdata[0]);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    cin >> N;
    int *h_a = new int[N];
    int *h_d = new int[N];
    for (int i = 0; i < N; i++){
        h_a[i] = ( (long long)i * 48271 + ((i >> 1) * 163) + 7 ) % 100000;
        h_d[i] = 1;
    }
    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));
    cudaMemcpy(d_a, h_a, N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d, N * sizeof(int), cudaMemcpyHostToDevice);

    int blockSize = 1024;
    for (int i = 1; i < N; i++){
        int numThreads = blockSize;
        int numBlocks = (i + numThreads - 1) / numThreads;
        int init = 1;
        cudaMemcpy(&d_d[i], &init, sizeof(int), cudaMemcpyHostToDevice);
        compute_dp<<<numBlocks, numThreads>>>(i, d_a, d_d);
        cudaDeviceSynchronize();
    }

    int *d_best;
    cudaMalloc(&d_best, sizeof(int));
    cudaMemset(d_best, 0, sizeof(int));
    int threads = 1024;
    int blocks = (N + threads * 2 - 1) / (threads * 2);
    reduce_max<<<blocks, threads, threads * sizeof(int)>>>(d_d, N, d_best);
    cudaDeviceSynchronize();

    int h_best;
    cudaMemcpy(&h_best, d_best, sizeof(int), cudaMemcpyDeviceToHost);
    cout << h_best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_best);
    delete[] h_a;
    delete[] h_d;
    return 0;
}

