__global__ void initKernel(uint64_t *d, int N, int L) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int w = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && w < L) {
        d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void popcountKernel(const uint64_t *d, int N, int L, unsigned long long *result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && j < N && i < j) {
        unsigned long long localSum = 0;
        for(int w = 0; w < L; w++){
            localSum += __popcll(d[(size_t)i * L + w] ^ d[(size_t)j * L + w]);
        }
        atomicAdd(result, localSum);
    }
}

