#include <iostream>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void gameKernel(const uint8_t* A, uint8_t* B, int H, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i >= H - 1 || j >= W - 1) return;
    int dr[8] = {-1,-1,-1,0,0,1,1,1};
    int dc[8] = {-1,0,1,-1,1,-1,0,1};
    int idx = i * W + j;
    int c = 0;
    for (int k = 0; k < 8; k++) {
        int ni = i + dr[k];
        int nj = j + dc[k];
        c += A[ni * W + nj];
    }
    uint8_t cell = A[idx];
    B[idx] = cell ? ((c==2 || c==3) ? 1 : 0) : ((c==3) ? 1 : 0);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    vector<uint8_t> h_A(H*W), h_B(H*W, 0);
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            h_A[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;

    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, H * W * sizeof(uint8_t));
    cudaMalloc(&d_B, H * W * sizeof(uint8_t));
    cudaMemcpy(d_A, h_A.data(), H * W * sizeof(uint8_t), cudaMemcpyHostToDevice);

    dim3 blockSize(16,16);
    dim3 gridSize(((W - 2) + blockSize.x - 1) / blockSize.x,
                  ((H - 2) + blockSize.y - 1) / blockSize.y);

    for (int t = 0; t < T; t++) {
        gameKernel<<<gridSize, blockSize>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        uint8_t* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A.data(), d_A, H * W * sizeof(uint8_t), cudaMemcpyDeviceToHost);
    long long s = 0;
    for (auto v : h_A) s += v;
    cout << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

