#include <iostream>
#include <cstdint>
#include <cuda_runtime.h>
using namespace std;

__global__ void initKernel(uint8_t *A, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = H * W;
    if (idx < total) {
        int i = idx / W;
        int j = idx % W;
        A[idx] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
    }
}

__global__ void simKernel(const uint8_t *A, uint8_t *B, int H, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    if(i >= 1 && i < H - 1 && j >= 1 && j < W - 1) {
        int idx = i * W + j;
        int c = 0;
        int dr[8] = {-1,-1,-1,0,0,1,1,1};
        int dc[8] = {-1,0,1,-1,1,-1,0,1};
        for (int k = 0; k < 8; k++) {
            int ni = i + dr[k];
            int nj = j + dc[k];
            c += A[ni * W + nj];
        }
        uint8_t cell = A[idx];
        B[idx] = cell ? (c == 2 || c == 3) : (c == 3);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    int total = H * W;

    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, total * sizeof(uint8_t));
    cudaMalloc(&d_B, total * sizeof(uint8_t));

    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;
    initKernel<<<gridSize, blockSize>>>(d_A, H, W);
    cudaDeviceSynchronize();

    dim3 threadsPerBlock(16,16);
    dim3 numBlocks((W + threadsPerBlock.x - 1) / threadsPerBlock.x, (H + threadsPerBlock.y - 1) / threadsPerBlock.y);

    for (int t = 0; t < T; t++) {
        simKernel<<<numBlocks, threadsPerBlock>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        uint8_t *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    uint8_t *h_A = new uint8_t[total];
    cudaMemcpy(h_A, d_A, total * sizeof(uint8_t), cudaMemcpyDeviceToHost);

    long long s = 0;
    for (int i = 0; i < total; i++)
        s += h_A[i];
    cout << s << "\n";

    delete[] h_A;
    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

