#define CUDA_CHECK(call) {                                          \
    cudaError_t err = call;                                         \
    if(err != cudaSuccess) {                                        \
        std::cerr << "CUDA error in " << __FILE__ << " at line "    \
                  << __LINE__ << ": " << cudaGetErrorString(err)    \
                  << std::endl;                                     \
        exit(err);                                                  \
    }                                                               \
}

__global__ void knapKernel(const int* dp_old, int* dp_new, int W, int weight, int value) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx > W) return;
    if(idx < weight) {
        dp_new[idx] = dp_old[idx];
    } else {
        int candidate = dp_old[idx - weight] + value;
        dp_new[idx] = max(dp_old[idx], candidate);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, W; 
    cin >> N >> W;
    vector<int> h_w(N), h_v(N);
    for (int i = 0; i < N; i++){
        h_w[i] = (i % 97) + 1;
        h_v[i] = (i * 31) % 1000 + 1;
    }
    // Initialize dp array on host.
    vector<int> h_dp(W+1, 0);

    // Allocate device memory.
    int *d_dp, *d_new;
    CUDA_CHECK( cudaMalloc((void**)&d_dp, (W+1)*sizeof(int)) );
    CUDA_CHECK( cudaMalloc((void**)&d_new, (W+1)*sizeof(int)) );
    CUDA_CHECK( cudaMemcpy(d_dp, h_dp.data(), (W+1)*sizeof(int), cudaMemcpyHostToDevice) );

    int blockSize = 256;
    int gridSize = (W+blockSize) / blockSize;

    // For each item, update dp array.
    for (int i = 0; i < N; i++){
        int weight = h_w[i];
        int value = h_v[i];
        knapKernel<<<gridSize, blockSize>>>(d_dp, d_new, W, weight, value);
        CUDA_CHECK( cudaGetLastError() );
        // Swap pointers d_dp and d_new.
        int* temp = d_dp;
        d_dp = d_new;
        d_new = temp;
    }

    // Copy result from device.
    CUDA_CHECK( cudaMemcpy(h_dp.data(), d_dp, (W+1)*sizeof(int), cudaMemcpyDeviceToHost) );
    cout << h_dp[W] << "\n";

    cudaFree(d_dp);
    cudaFree(d_new);
    return 0;
}

