#include <cuda_runtime.h>
#include <device_launch_parameters.h>
#include <cstdio>
#include <cstdlib>
#include <algorithm>
using namespace std;

__global__ void compute_d_kernel(const int* a, int* d, int i) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i) {
        if(a[j] < a[i]) {
            // atomicMax ensures that d[i] gets the maximum value among candidates.
            atomicMax(&d[i], d[j] + 1);
        }
    }
}

__global__ void reduce_max(const int *in, int *out, int n) {
    extern __shared__ int sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    int max_val = -1;
    if(idx < n)
        max_val = in[idx];
    if(idx + blockDim.x < n)
        max_val = max(max_val, in[idx + blockDim.x]);
    sdata[tid] = max_val;
    __syncthreads();

    for(unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if(tid < s) {
            sdata[tid] = max(sdata[tid], sdata[tid+s]);
        }
        __syncthreads();
    }
    if(tid == 0)
        out[blockIdx.x] = sdata[0];
}

int main(){
    int N;
    if(scanf("%d", &N) != 1) return 1;

    int* h_a = (int*)malloc(N * sizeof(int));
    int* h_d = (int*)malloc(N * sizeof(int));

    // Initialize arrays on host.
    for (int i = 0; i < N; i++){
        h_a[i] = (int)(((long long)i * 48271LL + (i >> 1) * 163LL + 7) % 100000);
        h_d[i] = 1;
    }

    // Allocate device arrays.
    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));

    cudaMemcpy(d_a, h_a, N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d, N * sizeof(int), cudaMemcpyHostToDevice);

    // For each i from 0 to N-1, update d[i] by scanning all j < i in parallel.
    for (int i = 0; i < N; i++){
        // Only launch kernel if there are any j to process.
        if(i > 0) {
            int threadsPerBlock = 256;
            int blocks = (i + threadsPerBlock - 1) / threadsPerBlock;
            compute_d_kernel<<<blocks, threadsPerBlock>>>(d_a, d_d, i);
            cudaDeviceSynchronize();
        }
    }

    // Reduction to find the maximum value in d array.
    int currSize = N;
    int *d_in = d_d;
    int *d_out;
    cudaMalloc((void**)&d_out, ((currSize + 511) / 512) * sizeof(int));
    while (currSize > 1) {
        int threadsPerBlock = 256;
        int blocks = (currSize + threadsPerBlock * 2 - 1) / (threadsPerBlock * 2);
        size_t sharedMemSize = threadsPerBlock * sizeof(int);
        reduce_max<<<blocks, threadsPerBlock, sharedMemSize>>>(d_in, d_out, currSize);
        cudaDeviceSynchronize();
        currSize = blocks;
        d_in = d_out;
    }

    int best;
    cudaMemcpy(&best, d_in, sizeof(int), cudaMemcpyDeviceToHost);
    printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_out);
    free(h_a);
    free(h_d);
    return 0;
}

