#include <iostream>
#include <cstdint>
#include <cuda_runtime.h>
using namespace std;

__global__ void initD(uint64_t* d, int L, int N) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * L;
    if (idx < total) {
        int i = idx / L;
        int w = idx % L;
        d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void popcountKernel(const uint64_t* d, int L, int N, unsigned long long* result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if (i < N && j < N && i < j) {
        unsigned long long local = 0;
        for (int w = 0; w < L; w++) {
            uint64_t val1 = d[(size_t)i * L + w];
            uint64_t val2 = d[(size_t)j * L + w];
            local += __popcll(val1 ^ val2);
        }
        atomicAdd(result, local);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;

    size_t sizeD = (size_t)N * L * sizeof(uint64_t);
    uint64_t* d_d;
    cudaMalloc(&d_d, sizeD);

    int totalThreads = N * L;
    int blockSize = 256;
    int gridSize = (totalThreads + blockSize - 1) / blockSize;
    initD<<<gridSize, blockSize>>>(d_d, L, N);
    cudaDeviceSynchronize();

    unsigned long long* d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (N + block.y - 1) / block.y);
    popcountKernel<<<grid, block>>>(d_d, L, N, d_result);
    cudaDeviceSynchronize();

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cout << h_result << "\n";

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
