#include <iostream>
#include <iomanip>
#include <cuda_runtime.h>
using namespace std;

__global__ void stencil(const double* A, double* B, int H, int W, double a) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    if(i > 0 && i < H-1 && j > 0 && j < W-1) {
        int id = i * W + j;
        B[id] = A[id] + a * ( A[(i-1)*W + j] + A[(i+1)*W + j] + A[i*W + (j-1)] + A[i*W + (j+1)] - 4 * A[id] );
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    int size = H * W;
    double *h_A = new double[size];

    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            h_A[i * W + j] = i * 0.1 + j * 0.2;
        }
    }

    double a = 0.125;

    double *d_A, *d_B;
    cudaMalloc(&d_A, size * sizeof(double));
    cudaMalloc(&d_B, size * sizeof(double));
    cudaMemcpy(d_A, h_A, size * sizeof(double), cudaMemcpyHostToDevice);

    dim3 block(16, 16);
    dim3 grid((W + block.x - 1) / block.x, (H + block.y - 1) / block.y);

    for (int t = 0; t < T; t++){
        stencil<<<grid, block>>>(d_A, d_B, H, W, a);
        cudaDeviceSynchronize();
        double* tmp = d_A;
        d_A = d_B;
        d_B = tmp;
    }

    cudaMemcpy(h_A, d_A, size * sizeof(double), cudaMemcpyDeviceToHost);
    double s = 0;
    for (int i = 0; i < size; i++){
        s += h_A[i];
    }
    cout.setf(ios::fixed);
    cout << setprecision(6) << s << "\n";

    delete[] h_A;
    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

