#include <cuda_runtime.h>
#include <iostream>
#include <algorithm>
using namespace std;

__global__ void update_dp(const int* dp, int* dp_new, int W, int weight, int value) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx <= W) {
        if(idx >= weight)
            dp_new[idx] = max(dp[idx], dp[idx - weight] + value);
        else
            dp_new[idx] = dp[idx];
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, W;
    cin >> N >> W;

    int *h_w = new int[N];
    int *h_v = new int[N];
    for(int i = 0; i < N; i++){
        h_w[i] = (i % 97) + 1;
        h_v[i] = ((i * 31) % 1000) + 1;
    }

    // Allocate host dp array (optional, for final result)
    int result;

    // Allocate device arrays for dp and temporary dp_new
    int *d_dp, *d_dp_new;
    cudaMalloc((void**)&d_dp, sizeof(int) * (W+1));
    cudaMalloc((void**)&d_dp_new, sizeof(int) * (W+1));

    // Initialize dp with zeros on device
    cudaMemset(d_dp, 0, sizeof(int)*(W+1));

    int blockSize = 256;
    int gridSize = (W + 1 + blockSize - 1) / blockSize;

    for(int i = 0; i < N; i++){
        int weight = h_w[i];
        int value  = h_v[i];
        update_dp<<<gridSize, blockSize>>>(d_dp, d_dp_new, W, weight, value);
        cudaDeviceSynchronize();
        // Swap pointers: new dp becomes dp for next iteration.
        int* temp = d_dp;
        d_dp = d_dp_new;
        d_dp_new = temp;
    }

    // Copy result from device: dp[W]
    cudaMemcpy(&result, d_dp + W, sizeof(int), cudaMemcpyDeviceToHost);
    cout << result << "\n";

    // Cleanup
    cudaFree(d_dp);
    cudaFree(d_dp_new);
    delete[] h_w;
    delete[] h_v;

    return 0;
}

