#include <cuda_runtime.h>
#include <iostream>
#include <cstdint>
#include <cstdlib>
using namespace std;

__global__ void gameOfLifeKernel(const uint8_t* A, uint8_t* B, int H, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i >= H-1 || j >= W-1) return;
    int idx = i * W + j;
    int neighborSum = 0;
    int dr[8] = {-1,-1,-1,0,0,1,1,1};
    int dc[8] = {-1,0,1,-1,1,-1,0,1};
    for (int k = 0; k < 8; k++){
        int ni = i + dr[k];
        int nj = j + dc[k];
        neighborSum += A[ni * W + nj];
    }
    uint8_t cell = A[idx];
    if(cell)
        B[idx] = (neighborSum == 2 || neighborSum == 3) ? 1 : 0;
    else
        B[idx] = (neighborSum == 3) ? 1 : 0;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, T;
    cin >> H >> W >> T;
    size_t size = H * W * sizeof(uint8_t);
    uint8_t *h_A = new uint8_t[H * W];
    uint8_t *h_B = new uint8_t[H * W];
    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            h_A[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
        }
    }
    // Allocate device memory
    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    // Copy initial board to device
    cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);
    // Define block and grid sizes
    dim3 blockDim(16, 16);
    dim3 gridDim((W - 2 + blockDim.x - 1) / blockDim.x, (H - 2 + blockDim.y - 1) / blockDim.y);
    // Run T iterations
    for (int t = 0; t < T; t++){
        gameOfLifeKernel<<<gridDim, blockDim>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        // Swap pointers: d_A becomes updated board, d_B becomes old board.
        uint8_t *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }
    // Copy final result back to host
    cudaMemcpy(h_A, d_A, size, cudaMemcpyDeviceToHost);
    long long s = 0;
    for (int i = 0; i < H * W; i++){
        s += h_A[i];
    }
