#include <cstdio>
#include <cstdint>
#include <cuda_runtime.h>

__global__ void init_kernel(uint64_t* d, int N, int L) {
    size_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    size_t total = (size_t)N * L;
    if (idx >= total) return;
    int i = idx / L;
    int w = idx % L;
    d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
}

__global__ void pairwise_kernel(const uint64_t* d, int N, int L, unsigned long long totalPairs, unsigned long long* result) {
    unsigned long long pair_index = blockIdx.x * blockDim.x + threadIdx.x;
    if (pair_index >= totalPairs) return;

    int i = 0;
    unsigned long long temp = pair_index;
    // Map linear pair index to (i,j)
    while (temp >= (unsigned)(N - i - 1)) {
        temp -= (N - i - 1);
        i++;
    }
    int j = i + 1 + temp;

    unsigned long long local_sum = 0;
    for (int w = 0; w < L; w++) {
        // Compute index for the two rows
        uint64_t a = d[(size_t)i * L + w];
        uint64_t b = d[(size_t)j * L + w];
        local_sum += __popcll(a ^ b);
    }

    atomicAdd(result, local_sum);
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2) return 1;

    size_t total_elements = (size_t)N * L;
    size_t d_size = total_elements * sizeof(uint64_t);
    uint64_t* d_d;
    cudaMalloc((void**)&d_d, d_size);

    int threadsPerBlock = 256;
    int blocks = (total_elements + threadsPerBlock - 1) / threadsPerBlock;
    init_kernel<<<blocks, threadsPerBlock>>>(d_d, N, L);
    cudaDeviceSynchronize();

    // total number of pairs = N*(N-1)/2
    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) / 2;
    unsigned long long* d_result;
    cudaMalloc((void**)&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    int pairThreads = 256;
    int pairBlocks = (totalPairs + pairThreads - 1) / pairThreads;
    pairwise_kernel<<<pairBlocks, pairThreads>>>(d_d, N, L, totalPairs, d_result);
    cudaDeviceSynchronize();

    unsigned long long h_result = 0;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    printf("%llu\n", h_result);

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

