#include <iostream>
#include <iomanip>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void updateKernel(const double *A, double *B, int H, int W, double a) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(i > 0 && i < H - 1 && j > 0 && j < W - 1) {
        int idx = i * W + j;
        int top = (i - 1) * W + j;
        int bottom = (i + 1) * W + j;
        int left = i * W + j - 1;
        int right = i * W + j + 1;
        B[idx] = A[idx] + a * (A[top] + A[bottom] + A[left] + A[right] - 4.0 * A[idx]);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    vector<double> h_A(H * W), h_B(H * W);
    for(int i = 0; i < H; i++)
        for(int j = 0; j < W; j++)
            h_A[i * W + j] = i * 0.1 + j * 0.2;

    double a = 0.125;

    double *d_A, *d_B;
    size_t size = H * W * sizeof(double);
    cudaMalloc((void**)&d_A, size);
    cudaMalloc((void**)&d_B, size);
    cudaMemcpy(d_A, h_A.data(), size, cudaMemcpyHostToDevice);

    dim3 blockDim(16, 16);
    dim3 gridDim((W + blockDim.x - 1) / blockDim.x, (H + blockDim.y - 1) / blockDim.y);

    for(int t = 0; t < T; t++){
        updateKernel<<<gridDim, blockDim>>>(d_A, d_B, H, W, a);
        cudaDeviceSynchronize();
        double *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A.data(), d_A, size, cudaMemcpyDeviceToHost);
    cudaFree(d_A);
    cudaFree(d_B);

    double s = 0;
    for(double v : h_A)
        s += v;

    cout.setf(ios::fixed);
    cout << setprecision(6) << s << "\n";
    return 0;
}

