#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cuda_runtime.h>
#include <iostream>
using namespace std;

__global__ void init_d(uint64_t* d, int N, int L) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int w = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && w < L) {
        d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void compute_popcounts(const uint64_t* d, int N, int L, unsigned long long totalIterations, unsigned long long* result) {
    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    if(tid >= totalIterations) return;

    // Mapping tid to (i,j,w)
    // tid corresponds to an iteration over all pairs (i,j) and w:
    // Let r = tid / L, and w = tid % L.
    unsigned long long r = tid / L;
    int w = tid % L;

    // We want to find i and j such that:
    // T(i) = i*N - (i*(i+1))/2 <= r < T(i+1) where T(i) = i*N - i*(i+1)/2.
    int low = 0, high = N;
    while(low < high) {
        int mid = (low + high) >> 1;
        unsigned long long Tmid = (unsigned long long)mid * N - (unsigned long long)mid * (mid + 1) / 2;
        if(Tmid <= r)
            low = mid + 1;
        else
            high = mid;
    }
    int i_val = low - 1;
    unsigned long long T_i = (unsigned long long)i_val * N - (unsigned long long)i_val * (i_val + 1) / 2;
    int j_val = (int)(r - T_i) + i_val + 1;

    uint64_t val1 = d[(size_t)i_val * L + w];
    uint64_t val2 = d[(size_t)j_val * L + w];
    unsigned long long pop = __popcll(val1 ^ val2);
    atomicAdd(result, pop);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;

    size_t size_d = (size_t)N * L * sizeof(uint64_t);
    uint64_t *d_d;
    cudaMalloc(&d_d, size_d);

    // Configure grid for initialization kernel.
    dim3 blockDimInit(16, 16);
    dim3 gridDimInit((N + blockDimInit.x - 1) / blockDimInit.x, (L + blockDimInit.y - 1) / blockDimInit.y);
    init_d<<<gridDimInit, blockDimInit>>>(d_d, N, L);
    cudaDeviceSynchronize();

    // Compute total iterations: (N*(N-1)/2)*L
    unsigned long long totalIterations = ((unsigned long long)N * (N - 1) / 2) * L;

    unsigned long long* d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    // Launch kernel for popcount computation.
    int blockSize = 256;
    int numBlocks = (totalIterations + blockSize - 1) / blockSize;
    compute_popcounts<<<numBlocks, blockSize>>>(d_d, N, L, totalIterations, d_result);
    cudaDeviceSynchronize();

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cout << h_result << "\n";

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

