__global__ void diffusionStep(const double *A, double *B, int H, int W, double a) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(i >= 1 && i < H-1 && j >= 1 && j < W-1) {
        int idx = i * W + j;
        B[idx] = A[idx] + a * (A[idx - W] + A[idx + W] + A[idx - 1] + A[idx + 1] - 4 * A[idx]);
    }
}

