__global__ void pairPopcount(const uint64_t* d, int N, int L, unsigned long long* result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if (i < N && j < N && j > i) {
        unsigned long long sum = 0;
        for (int w = 0; w < L; w++) {
            uint64_t val = d[(size_t)i * L + w] ^ d[(size_t)j * L + w];
            sum += __popcll(val);
        }
        atomicAdd(result, sum);
    }
}

int main(){
