    cin.tie(nullptr);
    int N, L;
    cin >> N >> L;
    vector<uint64_t> h_d((size_t)N * L);
    for (int i = 0; i < N; i++)
        for (int w = 0; w < L; w++)
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);

    uint64_t* d_d;
    size_t size = h_d.size() * sizeof(uint64_t);
    cudaMalloc(&d_d, size);
    cudaMemcpy(d_d, h_d.data(), size, cudaMemcpyHostToDevice);

