#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

#define THREADS_PER_BLOCK 1024

// Kernel to perform reduction over indices [0, current_i)
// For each index j, if (a[j] < a[current_i]) candidate = d[j]+1; else candidate = 1.
// Each block computes the maximum candidate in its portion.
__global__ void candidateReduction(const int *a, const int *d, int current_i, int *blockMax) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    int candidate = 1;
    if (idx < current_i) {
        candidate = (a[idx] < a[current_i]) ? d[idx] + 1 : 1;
    }
    sdata[tid] = candidate;
    __syncthreads();

    // Reduction in shared memory
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s && idx + s < current_i) {
            sdata[tid] = max(sdata[tid], sdata[tid + s]);
        }
        __syncthreads();
    }
    if (tid == 0) {
        blockMax[blockIdx.x] = sdata[0];
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N; 
    cin >> N;

    // Allocate and initialize host arrays
    vector<int> h_a(N), h_d(N, 1);
    for (int i = 0; i < N; i++){
        long long t = (long long)i * 48271LL + ((i >> 1) * 163LL) + 7;
        h_a[i] = t % 100000;
    }

    // Allocate device arrays
    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));

    cudaMemcpy(d_a, h_a.data(), N * sizeof(int), cudaMemcpyHostToDevice);
    // Initialize d on device with 1s.
    cudaMemcpy(d_d, h_d.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    int best = 0;

    // Preallocate a buffer for block partial maximums.
    int maxBlocks = (N + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    int *d_partial;
    cudaMalloc(&d_partial, maxBlocks * sizeof(int));
    vector<int> h_partial(maxBlocks);

    // For each element, compute d[i] by reducing over j in [0, i)
    for (int i = 0; i < N; i++){
        int currentVal;
        if(i == 0){
            currentVal = 1;
        } else {
            int threads = (i < THREADS_PER_BLOCK) ? i : THREADS_PER_BLOCK;
            int blocks = (i + threads - 1) / threads;

            candidateReduction<<<blocks, threads, threads * sizeof(int)>>>(d_a, d_d, i, d_partial);
            cudaDeviceSynchronize();

            // Copy partial results from device and reduce on host.
            cudaMemcpy(h_partial.data(), d_partial, blocks * sizeof(int), cudaMemcpyDeviceToHost);
            int localMax = 1;
            for (int j = 0; j < blocks; j++){
                localMax = max(localMax, h_partial[j]);
            }
            currentVal = localMax;
        }

        // Update d[i] on device.
        cudaMemcpy(d_d + i, &currentVal, sizeof(int), cudaMemcpyHostToDevice);
        best = max(best, currentVal);
    }

    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_partial);
    return 0;
}

