__global__ void computeHamming(const uint64_t* d, int N, int L, unsigned long long* globalSum) {
    unsigned long long totalPairs = ((unsigned long long)N*(N-1)) / 2;
    unsigned long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= totalPairs) return;

    // Map idx to (i, j) pair using inverse triangular number formula
    double temp = sqrt((double)((2LL * N - 1) * (2LL * N - 1) - 8.0 * idx));
    int i = (int)floor(((2.0 * N - 1.0) - temp) / 2.0);
    unsigned long long prevCount = ((unsigned long long)i * (2ULL * N - i - 1)) / 2;
    int j = i + 1 + (int)(idx - prevCount);

    unsigned long long localSum = 0;
    for (int w = 0; w < L; w++) {
        uint64_t val1 = d[(size_t)i * L + w];
        uint64_t val2 = d[(size_t)j * L + w];
        uint64_t x = val1 ^ val2;
        localSum += __popcll(x);
    }

    atomicAdd(globalSum, localSum);
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2) return 1;
    size_t total = (size_t)N * L;
    uint64_t* h_d = new uint64_t[total];
    for (int i = 0; i < N; i++){
        for (int w = 0; w < L; w++){
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    uint64_t* d_d;
    cudaMalloc((void**)&d_d, total * sizeof(uint64_t));
    cudaMemcpy(d_d, h_d, total * sizeof(uint64_t), cudaMemcpyHostToDevice);

    unsigned long long* d_result;
    cudaMalloc((void**)&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    unsigned long long totalPairs = ((unsigned long long)N*(N-1))/2;
    int threadsPerBlock = 256;
    int blocks = (totalPairs + threadsPerBlock - 1) / threadsPerBlock;
    computeHamming<<<blocks, threadsPerBlock>>>(d_d, N, L, d_result);
    cudaDeviceSynchronize();

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    printf("%llu\n", h_result);

    cudaFree(d_d);
    cudaFree(d_result);
