#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <iostream>
#include <vector>
using namespace std;

__global__ void computeDiffsKernel(const int* a, int N, unsigned long long totalPairs, long long* blockSums) {
    extern __shared__ long long sdata[];
    long long mySum = 0;
    unsigned long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long stride = (unsigned long long)blockDim.x * gridDim.x;
    while(idx < totalPairs) {
        double t = (double)(2LL * N - 1);
        double disc = t * t - 8.0 * (double)idx;
        double sqrt_disc = sqrt(disc);
        int i = (int)floor((t - sqrt_disc) / 2.0);
        unsigned long long offset = (unsigned long long)i * (2ULL * N - i - 1) / 2;
        int j = (int)((idx - offset) + i + 1);
        mySum += llabs((long long)a[i] - (long long)a[j]);
        idx += stride;
    }
    sdata[threadIdx.x] = mySum;
    __syncthreads();
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sdata[threadIdx.x] += sdata[threadIdx.x + s];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0)
        blockSums[blockIdx.x] = sdata[0];
}

__global__ void reduceKernel(long long* data, int n) {
    extern __shared__ long long sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int i = blockIdx.x * blockDim.x + tid;
    long long sum = (i < n) ? data[i] : 0;
    sdata[tid] = sum;
    __syncthreads();
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s)
            sdata[tid] += sdata[tid + s];
        __syncthreads();
    }
    if (tid == 0)
        data[blockIdx.x] = sdata[0];
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; i++){
        a[i] = (int)(((unsigned int)i * 1664525u + 1013904223u) % 1000003u);
    }

    int* d_a;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMemcpy(d_a, a.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) / 2;

    int threadsPerBlock = 256;
    int blocks = 256;
    long long* d_blockSums;
    cudaMalloc(&d_blockSums, blocks * sizeof(long long));

    computeDiffsKernel<<<blocks, threadsPerBlock, threadsPerBlock * sizeof(long long)>>>(d_a, N, totalPairs, d_blockSums);

    int numElements = blocks;
    while(numElements > 1){
        int blockCount = (numElements + threadsPerBlock - 1) / threadsPerBlock;
        reduceKernel<<<blockCount, threadsPerBlock, threadsPerBlock * sizeof(long long)>>>(d_blockSums, numElements);
        numElements = blockCount;
    }

    long long result;
    cudaMemcpy(&result, d_blockSums, sizeof(long long), cudaMemcpyDeviceToHost);
    cout << result << "\n";

    cudaFree(d_a);
    cudaFree(d_blockSums);
    return 0;
}

