using namespace std;

#define CHECK(call)                                                         \
{                                                                           \
    const cudaError_t error = call;                                         \
    if (error != cudaSuccess)                                               \
    {                                                                       \
        printf("Error: %s:%d, ", __FILE__, __LINE__);                       \
        printf("code: %d, reason: %s\n", error, cudaGetErrorString(error));  \
        exit(1);                                                            \
    }                                                                       \
}

__global__ void initArrays(int *a, int *d, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        // Compute a[i] using 64-bit arithmetic.
        long long t = (long long)i * 48271LL + ((i >> 1) * 163LL) + 7;
        a[i] = (int)(t % 100000);
        d[i] = 1;
    }
}

__global__ void dpKernel(const int *a, int *d, int i) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i) {
        if(a[j] < a[i]) {
            atomicMax(&d[i], d[j] + 1);
        }
    }
}

__global__ void reduceMax(const int *d, int *out, int N) {
    extern __shared__ int sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    int myMax = 0;
    if(idx < N)
        myMax = d[idx];
    if(idx + blockDim.x < N)
        myMax = max(myMax, d[idx + blockDim.x]);
    sdata[tid] = myMax;
    __syncthreads();

    for(unsigned int s = blockDim.x/2; s > 0; s >>= 1) {
        if(tid < s)
            sdata[tid] = max(sdata[tid], sdata[tid + s]);
        __syncthreads();
    }
    if(tid == 0)
        out[blockIdx.x] = sdata[0];
}

int main(){
    int N;
    scanf("%d", &N);

    int *d_a, *d_d;
    CHECK(cudaMalloc((void**)&d_a, N * sizeof(int)));
    CHECK(cudaMalloc((void**)&d_d, N * sizeof(int)));

    int blockSize = 256;
    int gridSize = (N + blockSize - 1) / blockSize;
    initArrays<<<gridSize, blockSize>>>(d_a, d_d, N);
    CHECK(cudaDeviceSynchronize());

    // Process dp for each i sequentially,
    // parallelizing the inner loop via CUDA threads.
    for (int i = 1; i < N; i++) {
        int threads = min(i, blockSize);
        int blocks = (i + threads - 1) / threads;
        dpKernel<<<blocks, threads>>>(d_a, d_d, i);
        CHECK(cudaDeviceSynchronize());
    }

    // Reduction to find the maximum value in d array.
    int currentSize = N;
    int *d_in = d_d;
    int *d_out;
    CHECK(cudaMalloc((void**)&d_out, currentSize * sizeof(int)));
    while(currentSize > 1) {
        int threadsR = 256;
        int blocksR = (currentSize + threadsR * 2 - 1) / (threadsR * 2);
        reduceMax<<<blocksR, threadsR, threadsR * sizeof(int)>>>(d_in, d_out, currentSize);
        CHECK(cudaDeviceSynchronize());
        currentSize = blocksR;
        // Swap pointers: next reduction will read from d_out.
        d_in = d_out;
    }

    int best;
    CHECK(cudaMemcpy(&best, d_in, sizeof(int), cudaMemcpyDeviceToHost));
    printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_out);
    return 0;
}

