const int MOD = 1000000007;

__global__ void initA(int n, int k, int *A) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx < n * k) {
        int i = idx / k;
        int x = idx % k;
        A[idx] = (i + 3 * x) % 1009;
    }
}

__global__ void initB(int k, int m, int *B) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx < k * m) {
        int x = idx / m;
        int j = idx % m;
        B[idx] = (x + 7 * j) % 1009;
    }
}

__global__ void matMul(int n, int k, int m, const int *A, const int *B, int *C) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx < n * m) {
        int i = idx / m;
        int j = idx % m;
        long long sum = 0;
        for (int x = 0; x < k; x++) {
            sum = (sum + 1LL * A[i * k + x] * B[x * m + j]) % MOD;
        }
        C[idx] = (int) sum;
    }
}

__global__ void reduceKernel(const int *input, int size, int *partialSums) {
    extern __shared__ int sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    int sum = 0;
    if(idx < size)
        sum = input[idx];
    if(idx + blockDim.x < size)
        sum = (sum + input[idx + blockDim.x]) % MOD;
    sdata[tid] = sum;
    __syncthreads();
    for (unsigned int s = blockDim.x / 2; s > 0; s >>= 1) {
        if(tid < s) {
            sdata[tid] = (sdata[tid] + sdata[tid + s]) % MOD;
        }
        __syncthreads();
    }
    if(tid == 0)
        partialSums[blockIdx.x] = sdata[0];
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, m;
    cin >> n >> k >> m;

    int sizeA = n * k;
    int sizeB = k * m;
    int sizeC = n * m;

    int *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sizeA * sizeof(int));
    cudaMalloc(&d_B, sizeB * sizeof(int));
    cudaMalloc(&d_C, sizeC * sizeof(int));
    cudaMemset(d_C, 0, sizeC * sizeof(int));

    int blockSize = 256;
    int gridA = (sizeA + blockSize - 1) / blockSize;
    int gridB = (sizeB + blockSize - 1) / blockSize;
    int gridC = (sizeC + blockSize - 1) / blockSize;

    initA<<<gridA, blockSize>>>(n, k, d_A);
    initB<<<gridB, blockSize>>>(k, m, d_B);
    matMul<<<gridC, blockSize>>>(n, k, m, d_A, d_B, d_C);

    // Reduction to compute final sum on device
    int currentSize = sizeC;
    int *d_in = d_C;
    int *d_out = nullptr;
    while(currentSize > 1) {
        int threads = 256;
        int blocks = (currentSize + threads * 2 - 1) / (threads * 2);
        cudaMalloc(&d_out, blocks * sizeof(int));
        reduceKernel<<<blocks, threads, threads * sizeof(int)>>>(d_in, currentSize, d_out);
        if(d_in != d_C)
            cudaFree(d_in);
        d_in = d_out;
        currentSize = blocks;
        d_out = nullptr;
    }

