#include <cuda_runtime.h>
#include <iostream>
#include <cstdint>
using namespace std;

__global__ void initKernel(uint8_t *A, int H, int W) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = H * W;
    if(idx < total) {
        int i = idx / W;
        int j = idx % W;
        A[idx] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
    }
}

__global__ void updateKernel(const uint8_t *A, uint8_t *B, int H, int W) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int interior = (H - 2) * (W - 2);
    if(idx < interior) {
        int i = idx / (W - 2) + 1;
        int j = idx % (W - 2) + 1;
        int base = i * W + j;
        int count = 0;
        int dr[8] = {-1,-1,-1,0,0,1,1,1};
        int dc[8] = {-1,0,1,-1,1,-1,0,1};
        for (int k = 0; k < 8; k++) {
            int ni = i + dr[k];
            int nj = j + dc[k];
            count += A[ni * W + nj];
        }
        uint8_t cur = A[base];
        B[base] = cur ? (count == 2 || count == 3) : (count == 3);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    size_t size = H * W * sizeof(uint8_t);

    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);

    int threads = 256;
    int blocks = (H * W + threads - 1) / threads;
    initKernel<<<blocks, threads>>>(d_A, H, W);
    cudaDeviceSynchronize();

    int interior = (H - 2) * (W - 2);
    int updateThreads = 256;
    int updateBlocks = (interior + updateThreads - 1) / updateThreads;

    for (int t = 0; t < T; t++){
        updateKernel<<<updateBlocks, updateThreads>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        // Swap pointers
        uint8_t *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    uint8_t *h_A = new uint8_t[H * W];
    cudaMemcpy(h_A, d_A, size, cudaMemcpyDeviceToHost);

    long long s = 0;
    for (int i = 0; i < H * W; i++){
        s += h_A[i];
    }
    cout << s << "\n";

    delete[] h_A;
    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

