#include <iostream>

using namespace std;

__global__ void fillKernel(uint64_t *d, int N, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * L;
    if(idx < total) {
        int i = idx / L;
        int w = idx % L;
        d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void popcountKernel(const uint64_t *d, int N, int L, unsigned long long *result) {
    int i = blockIdx.x;
    int j = blockIdx.y * blockDim.x + threadIdx.x;
    if(j < N && j > i) {
        unsigned long long local_sum = 0;
        for (int w = 0; w < L; w++) {
            uint64_t a = d[(size_t)i * L + w];
            uint64_t b = d[(size_t)j * L + w];
            local_sum += __popcll(a ^ b);
        }
        atomicAdd(result, local_sum);
    }
}

int main(){
