#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void countBitsKernel(const uint64_t *d, unsigned long long totalTasks, int N, int L, unsigned long long *result) {
    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long stride = gridDim.x * blockDim.x;
    unsigned long long localSum = 0;
    for (unsigned long long t = tid; t < totalTasks; t += stride) {
        int w = t % L;
        unsigned long long pairIndex = t / L;
        int i = 0;
        unsigned long long cnt = (unsigned long long)(N - 1);
        while (pairIndex >= cnt) {
            pairIndex -= cnt;
            i++;
            cnt = (unsigned long long)(N - i - 1);
        }
        int j = i + 1 + pairIndex;
        uint64_t a = d[(unsigned long long)i * L + w];
        uint64_t b = d[(unsigned long long)j * L + w];
        uint64_t x = a ^ b;
        localSum += __popcll(x);
    }
    atomicAdd(result, localSum);
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2){
        return 1;
    }
    size_t dSize = (size_t)N * L;
    uint64_t *h_d = (uint64_t*)malloc(dSize * sizeof(uint64_t));
    for (int i = 0; i < N; i++){
        for (int w = 0; w < L; w++){
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    // Allocate device memory for d array.
    uint64_t *d_d;
    cudaMalloc(&d_d, dSize * sizeof(uint64_t));
    cudaMemcpy(d_d, h_d, dSize * sizeof(uint64_t), cudaMemcpyHostToDevice);

    // Compute total tasks = (# pairs) * L, where # pairs = N*(N-1)/2.
    unsigned long long numPairs = ((unsigned long long)N * (N - 1)) / 2;
    unsigned long long totalTasks = numPairs * L;

    // Allocate device memory for result.
    unsigned long long *d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    // Launch kernel.
    int threadsPerBlock = 256;
    int blocks = 1024;
    countBitsKernel<<<blocks, threadsPerBlock>>>(d_d, totalTasks, N, L, d_result);
