#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cuda_runtime.h>
#include <stdint.h>

__global__ void fillKernel(uint64_t* d, int N, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * L;
    if (idx < total) {
        int i = idx / L;
        int w = idx % L;
        d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void popcountKernel(const uint64_t* d, int N, int L, unsigned long long* sum) {
    // Total number of pairs = N*(N-1)/2
    long long totalPairs = ((long long)N*(N-1))/2;
    long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= totalPairs) return;

    // Map tid to pair (i, j)
    // Solve i*(2N - i - 1)/2 <= tid < (i+1)*(2N - i - 2)/2
    // Using quadratic formula.
    double temp = (sqrt((double)( (2LL * N - 1) * (2LL * N - 1) - 8.0 * tid )) - (2.0 * N - 1)) / (-2.0);
    int i = (int)temp;
    long long offset = ((long long)i * (2LL * N - i - 1)) / 2;
    int j = tid - offset + i + 1;

    unsigned long long local = 0;
    for (int w = 0; w < L; w++) {
        uint64_t a = d[(size_t)i * L + w];
        uint64_t b = d[(size_t)j * L + w];
        local += __popcll(a ^ b);
    }
    atomicAdd(sum, local);
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2) {
        return 1;
    }

    size_t dSize = (size_t)N * L * sizeof(uint64_t);
    uint64_t *h_d = (uint64_t*)malloc(dSize);
    if (!h_d) return 1;

    // Allocate device memory.
    uint64_t *d_d;
    cudaMalloc((void**)&d_d, dSize);

    // Fill data in parallel on device.
    int totalElements = N * L;
    int blockSize = 256;
    int gridSize = (totalElements + blockSize - 1) / blockSize;
    fillKernel<<<gridSize, blockSize>>>(d_d, N, L);
    cudaDeviceSynchronize();

    // Allocate device memory for result.
    unsigned long long *d_sum;
    cudaMalloc((void**)&d_sum, sizeof(unsigned long long));
    cudaMemset(d_sum, 0, sizeof(unsigned long long));

    // Launch popcount kernel.
    long long totalPairs = ((long long)N*(N-1))/2;
    gridSize = (totalPairs + blockSize - 1) / blockSize;
    popcountKernel<<<gridSize, blockSize>>>(d_d, N, L, d_sum);
    cudaDeviceSynchronize();

    // Copy result back to host.
    unsigned long long h_sum = 0;
    cudaMemcpy(&h_sum, d_sum, sizeof(unsigned long long), cudaMemcpyDeviceToHost);

    printf("%llu\n", h_sum);

    cudaFree(d_d);
    cudaFree(d_sum);
    free(h_d);
    return 0;
}

