#include <cstdint>
#include <cuda_runtime.h>
using namespace std;

__global__ void updateKernel(const uint8_t* A, uint8_t* B, int H, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i < H - 1 && j < W - 1) {
        int idx = i * W + j;
        int count = 0;
        int dr[8] = {-1,-1,-1,0,0,1,1,1};
        int dc[8] = {-1,0,1,-1,1,-1,0,1};
        for (int k = 0; k < 8; k++){
            int ni = i + dr[k], nj = j + dc[k];
            count += A[ni * W + nj];
        }
        uint8_t cell = A[idx];
        B[idx] = cell ? ((count == 2) || (count == 3)) : (count == 3);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, T;
    cin >> H >> W >> T;
    vector<uint8_t> h_A(H * W), h_B(H * W);
    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            h_A[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
        }
    }

    uint8_t *d_A, *d_B;
    size_t size = H * W * sizeof(uint8_t);
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMemcpy(d_A, h_A.data(), size, cudaMemcpyHostToDevice);

    dim3 blockDim(16, 16);
    int gridX = (W - 2 + blockDim.x - 1) / blockDim.x;
    int gridY = (H - 2 + blockDim.y - 1) / blockDim.y;
    dim3 gridDim(gridX, gridY);

    for (int t = 0; t < T; t++){
        updateKernel<<<gridDim, blockDim>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        // Swap pointers
        uint8_t *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A.data(), d_A, size, cudaMemcpyDeviceToHost);
    long long s = 0;
    for (auto v : h_A) s += v;
    cout << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

