#include <cstdio>
#include <cuda_runtime.h>
#define MOD 1000000007
#define MOD_AB 1009

__global__ void initA(int *A, int n, int k) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n * k) {
        int i = idx / k;
        int x = idx % k;
        A[idx] = (i + 3 * x) % MOD_AB;
    }
}

__global__ void initB(int *B, int k, int m) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < k * m) {
        int x = idx / m;
        int j = idx % m;
        B[idx] = (x + 7 * j) % MOD_AB;
    }
}

__global__ void matMul(int *A, int *B, int *C, int n, int k, int m) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n * m) {
        int i = idx / m;
        int j = idx % m;
        long long sum = 0;
        for (int x = 0; x < k; x++) {
            sum = (sum + (long long)A[i * k + x] * B[x * m + j]) % MOD;
        }
        C[idx] = (int)sum;
    }
}

__global__ void reduceKernel(int *in, int *out, int N) {
    extern __shared__ int sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int temp = 0;
    if (idx < N) temp = in[idx];
    sdata[tid] = temp;
    __syncthreads();
    for (unsigned int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            int other = sdata[tid + s];
            sdata[tid] = (sdata[tid] + other) % MOD;
        }
        __syncthreads();
    }
    if (tid == 0) out[blockIdx.x] = sdata[0];
}

int main(){
    int n, k, m;
    scanf("%d %d %d", &n, &k, &m);
    int sizeA = n * k, sizeB = k * m, sizeC = n * m;
    int *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sizeA * sizeof(int));
    cudaMalloc(&d_B, sizeB * sizeof(int));
    cudaMalloc(&d_C, sizeC * sizeof(int));
    cudaMemset(d_C, 0, sizeC * sizeof(int));

    int blockSize = 256;
    int gridA = (sizeA + blockSize - 1) / blockSize;
    int gridB = (sizeB + blockSize - 1) / blockSize;
    initA<<<gridA, blockSize>>>(d_A, n, k);
    initB<<<gridB, blockSize>>>(d_B, k, m);
    cudaDeviceSynchronize();

    int gridC = (sizeC + blockSize - 1) / blockSize;
    matMul<<<gridC, blockSize>>>(d_A, d_B, d_C, n, k, m);
    cudaDeviceSynchronize();

    int *d_in = d_C;
    int N = sizeC;
    int *d_out;
    cudaMalloc(&d_out, ((N + blockSize - 1) / blockSize) * sizeof(int));
    while (N > 1) {
        int gridSize = (N + blockSize - 1) / blockSize;
        reduceKernel<<<gridSize, blockSize, blockSize * sizeof(int)>>>(d_in, d_out, N);
        cudaDeviceSynchronize();
        N = gridSize;
        d_in = d_out;
    }
    int h_sum;
    cudaMemcpy(&h_sum, d_in, sizeof(int), cudaMemcpyDeviceToHost);
    printf("%d\n", h_sum % MOD);

    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
    cudaFree(d_out);
    return 0;
}

