#include <cmath>
using namespace std;

#define CUDA_CHECK(err) \
    if(err != cudaSuccess){ \
        fprintf(stderr, "CUDA Error: %s (err_num=%d) at %s:%d\n", cudaGetErrorString(err), err, __FILE__, __LINE__); \
        exit(EXIT_FAILURE); \
    }

__global__ void fillKernel(int *a, int N) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if(idx < N) {
        unsigned int val = idx * 1664525u + 1013904223u;
        a[idx] = val % 1000003;
    }
}

__global__ void diffKernel(const int *a, int N, unsigned long long *sum, unsigned long long M) {
    unsigned long long tid = blockDim.x * blockIdx.x + threadIdx.x;
    unsigned long long totalThreads = (unsigned long long)gridDim.x * blockDim.x;
    unsigned long long localSum = 0;
    for (unsigned long long k = tid; k < M; k += totalThreads) {
        // Binary search to find i such that S(i) <= k < S(i+1)
        int low = 0, high = N - 1, candidate = 0;
        while(low <= high) {
            int mid = (low + high) / 2;
            unsigned long long S_mid = ((unsigned long long)mid * (2ULL * N - mid - 1)) / 2ULL;
            if(S_mid <= k) {
                candidate = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        int i = candidate;
        unsigned long long S_i = ((unsigned long long)i * (2ULL * N - i - 1)) / 2ULL;
        int j = (int)(k - S_i + i + 1);
        int diff = a[i] - a[j];
        if(diff < 0) diff = -diff;
        localSum += (unsigned long long) diff;
    }
    atomicAdd(sum, localSum);
}

int main(){
    int N;
    if(scanf("%d", &N) != 1){
        fprintf(stderr, "Failed to read N\n");
        return EXIT_FAILURE;
    }

    int *d_a;
    CUDA_CHECK(cudaMalloc((void**)&d_a, N * sizeof(int)));

    int threadsPerBlock = 256;
    int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;
    fillKernel<<<blocks, threadsPerBlock>>>(d_a, N);
    CUDA_CHECK(cudaGetLastError());

    // Total number of pairs: M = N*(N-1)/2
    unsigned long long M = ((unsigned long long)N * (N - 1)) / 2ULL;

    unsigned long long *d_sum;
    CUDA_CHECK(cudaMalloc((void**)&d_sum, sizeof(unsigned long long)));
    CUDA_CHECK(cudaMemset(d_sum, 0, sizeof(unsigned long long)));

    // Launch diffKernel with enough threads over total pairs
    int totalThreads = 256 * 256;
    int diffBlocks = (totalThreads + threadsPerBlock - 1) / threadsPerBlock;
    diffKernel<<<diffBlocks, threadsPerBlock>>>(d_a, N, d_sum, M);
    CUDA_CHECK(cudaGetLastError());

    unsigned long long h_sum = 0;
    CUDA_CHECK(cudaMemcpy(&h_sum, d_sum, sizeof(unsigned long long), cudaMemcpyDeviceToHost));

    printf("%llu\n", h_sum);

    cudaFree(d_a);
    cudaFree(d_sum);
    return 0;
}

