#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <stdint.h>
using namespace std;

__global__ void updateKernel(const uint8_t* A, uint8_t* B, int H, int W) {
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    if(i >= H-1 || j >= W-1) return;
    const int dr[8] = {-1,-1,-1,0,0,1,1,1};
    const int dc[8] = {-1,0,1,-1,1,-1,0,1};
    int idx = i * W + j;
    int cnt = 0;
    for(int k = 0; k < 8; k++){
        int ni = i + dr[k];
        int nj = j + dc[k];
        cnt += A[ni * W + nj];
    }
    uint8_t cur = A[idx];
    // Game of Life rule update
    B[idx] = cur ? (cnt == 2 || cnt == 3) : (cnt == 3);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;

    vector<uint8_t> h_A(H * W);
    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            h_A[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
        }
    }

    uint8_t *d_A, *d_B;
    size_t size = H * W * sizeof(uint8_t);
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);

    cudaMemcpy(d_A, h_A.data(), size, cudaMemcpyHostToDevice);
    cudaMemset(d_B, 0, size);

    dim3 blockDim(16, 16);
    dim3 gridDim((W-2 + blockDim.x - 1) / blockDim.x, (H-2 + blockDim.y - 1) / blockDim.y);

    for(int t = 0; t < T; t++){
        updateKernel<<<gridDim, blockDim>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        // Swap pointers d_A and d_B
        uint8_t* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A.data(), d_A, size, cudaMemcpyDeviceToHost);

    long long sum = 0;
    for(auto v : h_A){
        sum += v;
    }
    cout << sum << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

