__global__ void init_a_kernel(int *a, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        // Using 64-bit arithmetic for multiplication as in original code
        long long temp = (long long)i * 48271LL + ((i >> 1) * 163LL) + 7;
        a[i] = (int)(temp % 100000);
    }
}

__global__ void init_d_kernel(int *d, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        d[i] = 1;
    }
}

__global__ void compute_dp_kernel(const int *a, const int *d, int i, int *res) {
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int ai = a[i];
    for (int j = tid; j < i; j += stride) {
        if(a[j] < ai) {
            int candidate = d[j] + 1;
            atomicMax(res, candidate);
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
