    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));

    int threadsPerBlock = 256;
    int blocks = (N + threadsPerBlock - 1) / threadsPerBlock;
    init_a_kernel<<<blocks, threadsPerBlock>>>(d_a, N);
    init_d_kernel<<<blocks, threadsPerBlock>>>(d_d, N);
    cudaDeviceSynchronize();

    int best = 1;
    int *d_res;
    cudaMalloc(&d_res, sizeof(int));

    for(int i = 1; i < N; i++){
        int initVal = 1;
        cudaMemcpy(d_res, &initVal, sizeof(int), cudaMemcpyHostToDevice);
        int innerThreads = 256;
        int innerBlocks = (i + innerThreads - 1) / innerThreads;
        compute_dp_kernel<<<innerBlocks, innerThreads>>>(d_a, d_d, i, d_res);
        cudaDeviceSynchronize();
        int candidate;
        cudaMemcpy(&candidate, d_res, sizeof(int), cudaMemcpyDeviceToHost);
        // Write dp[i] back into d_d
        cudaMemcpy(d_d + i, &candidate, sizeof(int), cudaMemcpyHostToDevice);
        best = max(best, candidate);
    }

    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_res);
    return 0;
}

