#include <iostream>
#include <vector>
#include <algorithm>
#include <cuda_runtime.h>
#include <device_launch_parameters.h>
using namespace std;

__global__ void knapSackKernel(const int item_weight, const int item_value, int* dp, int* dp_new, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j <= W) {
        if(j >= item_weight)
            dp_new[j] = max(dp[j], dp[j - item_weight] + item_value);
        else
            dp_new[j] = dp[j];
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, W;
    cin >> N >> W;
    vector<int> host_w(N), host_v(N);
    for (int i = 0; i < N; i++){
        host_w[i] = (i % 97) + 1;
        host_v[i] = (i * 31) % 1000 + 1;
    }
    vector<int> host_dp(W + 1, 0);

    int *d_dp, *d_dp_new;
    cudaMalloc(&d_dp, (W + 1) * sizeof(int));
    cudaMalloc(&d_dp_new, (W + 1) * sizeof(int));
    cudaMemcpy(d_dp, host_dp.data(), (W + 1) * sizeof(int), cudaMemcpyHostToDevice);

    int blockSize = 256;
    int numBlocks = (W + 1 + blockSize - 1) / blockSize;

    for (int i = 0; i < N; i++){
        int item_weight = host_w[i];
        int item_value = host_v[i];
        knapSackKernel<<<numBlocks, blockSize>>>(item_weight, item_value, d_dp, d_dp_new, W);
        cudaDeviceSynchronize();
        int* temp = d_dp;
        d_dp = d_dp_new;
        d_dp_new = temp;
    }

    cudaMemcpy(host_dp.data(), d_dp, (W + 1) * sizeof(int), cudaMemcpyDeviceToHost);
    cout << host_dp[W] << "\n";

    cudaFree(d_dp);
    cudaFree(d_dp_new);
    return 0;
}

