#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <cstdlib>

__global__ void calcKernel(const uint64_t* d, int N, int L, unsigned long long totalPairs, unsigned long long *result) {
    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long totalOps = totalPairs * (unsigned long long)L;
    for (unsigned long long idx = tid; idx < totalOps; idx += blockDim.x * gridDim.x) {
        unsigned long long p = idx / L;  // pair index
        int w = idx % L;
        // Decode (i, j) from pair index p using quadratic formula:
        // f(i)= i*(2*N - i - 1)/2. Solve for i satisfying f(i) <= p < f(i+1)
        double temp = (2.0 * N - 1.0);
        double disc = sqrt(temp * temp - 8.0 * p);
        int i_val = (int)floor((temp - disc) / 2.0);
        unsigned long long f_i = ((unsigned long long)i_val * (2ULL * N - i_val - 1ULL)) / 2ULL;
        int j_val = i_val + 1 + (int)(p - f_i);
        uint64_t a = d[(size_t)i_val * L + w];
        uint64_t b = d[(size_t)j_val * L + w];
        unsigned int pop = __popcll(a ^ b);
        atomicAdd(result, (unsigned long long)pop);
    }
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2) return 1;
    size_t total_d = (size_t)N * L;
    uint64_t* h_d = (uint64_t*)malloc(total_d * sizeof(uint64_t));
    for (int i = 0; i < N; i++){
        for (int w = 0; w < L; w++){
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }
    // Allocate device memory for d and copy
    uint64_t* d_d;
    cudaMalloc((void**)&d_d, total_d * sizeof(uint64_t));
    cudaMemcpy(d_d, h_d, total_d * sizeof(uint64_t), cudaMemcpyHostToDevice);
    free(h_d);
    // Calculate total number of pairs: N*(N-1)/2
    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) / 2;
    unsigned long long h_result = 0;
    unsigned long long* d_result;
    cudaMalloc((void**)&d_result, sizeof(unsigned long long));
    cudaMemcpy(d_result, &h_result, sizeof(unsigned long long), cudaMemcpyHostToDevice);
    // Launch kernel
    int threadsPerBlock = 256;
    int blocks = (int)((totalPairs * (unsigned long long)L + threadsPerBlock - 1) / threadsPerBlock);
    calcKernel<<<blocks, threadsPerBlock>>>(d_d, N, L, totalPairs, d_result);
    cudaDeviceSynchronize();
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    printf("%llu\n", h_result);
    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

