#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;

__global__ void life_kernel(const uint8_t* A, uint8_t* B, int H, int W) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i >= H-1 || j >= W-1) return;

    int dr[8] = {-1,-1,-1,0,0,1,1,1};
    int dc[8] = {-1,0,1,-1,1,-1,0,1};

    int c = 0;
    int idx = i * W + j;
    for (int k = 0; k < 8; k++) {
        int ni = i + dr[k];
        int nj = j + dc[k];
        c += A[ni * W + nj];
    }
    uint8_t cell = A[idx];
    // Apply the rules
    if(cell)
        B[idx] = (c == 2 || c == 3) ? 1 : 0;
    else
        B[idx] = (c == 3) ? 1 : 0;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;

    vector<uint8_t> host_A(H * W, 0);
    vector<uint8_t> host_B(H * W, 0);

    // Initialize A
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            host_A[i * W + j] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
        }
    }

    // Allocate device arrays
    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, H * W * sizeof(uint8_t));
    cudaMalloc(&d_B, H * W * sizeof(uint8_t));

    // Copy initial state to device
    cudaMemcpy(d_A, host_A.data(), H * W * sizeof(uint8_t), cudaMemcpyHostToDevice);

    // Kernel launch configuration for interior cells [1, H-2]x[1, W-2]
    dim3 blockDim(16, 16);
    dim3 gridDim((W-2 + blockDim.x - 1) / blockDim.x, (H-2 + blockDim.y - 1) / blockDim.y);

    // Run simulation T iterations
    for(int t = 0; t < T; t++){
        life_kernel<<<gridDim, blockDim>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        // Swap pointers for next iteration
        uint8_t* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    // Copy result back to host
    cudaMemcpy(host_A.data(), d_A, H * W * sizeof(uint8_t), cudaMemcpyDeviceToHost);

    long long s = 0;
    for(auto v : host_A) s += v;
    cout << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

