#include <cstdio>
#include <cstdlib>
#include <algorithm>
#include <cuda_runtime.h>

#define MOD 100000

__global__ void fillA(int *a, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        // Using long long for multiplication
        a[i] = (int)(((long long)i * 48271LL + ((i >> 1) * 163LL) + 7) % MOD);
    }
}

__global__ void fillOnes(int *d, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        d[i] = 1;
    }
}

__global__ void computeCandidate(const int *a, const int *d, int i, int *candidate) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i) {
        if(a[j] < a[i]) {
            int val = d[j] + 1;
            atomicMax(candidate, val);
        }
    }
}

int main(){
    int N;
    if(scanf("%d", &N) != 1) return EXIT_FAILURE;

    int *h_a = (int*)malloc(N * sizeof(int));
    int *h_d = (int*)malloc(N * sizeof(int));

    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));

    // Fill array a on device
    int blockSize = 256;
    int gridSize = (N + blockSize - 1) / blockSize;
    fillA<<<gridSize, blockSize>>>(d_a, N);
    cudaDeviceSynchronize();

    // Initialize dp array d with 1's on device
    fillOnes<<<gridSize, blockSize>>>(d_d, N);
    cudaDeviceSynchronize();

    // Copy a from device to host for access to a[i] in the host loop later.
    cudaMemcpy(h_a, d_a, N * sizeof(int), cudaMemcpyDeviceToHost);

    // We'll update dp sequentially in host for index i, but inner loop parallelized.
    int best = 1;
    // h_d[0] remains 1 (already set)
    h_d[0] = 1;

    // Candidate pointer on device for reduction.
    int *d_candidate;
    cudaMalloc((void**)&d_candidate, sizeof(int));

    for (int i = 1; i < N; i++){
        // initialize candidate = 1 on device
        int initCandidate = 1;
        cudaMemcpy(d_candidate, &initCandidate, sizeof(int), cudaMemcpyHostToDevice);

        // Launch kernel over j in [0, i)
        int threads = 256;
        int blocks = (i + threads - 1) / threads;
        computeCandidate<<<blocks, threads>>>(d_a, d_d, i, d_candidate);
        cudaDeviceSynchronize();

        int candidate;
        cudaMemcpy(&candidate, d_candidate, sizeof(int), cudaMemcpyDeviceToHost);
        h_d[i] = candidate;
        best = std::max(best, h_d[i]);

        // Update computed dp value on device
        cudaMemcpy(&d_d[i], &h_d[i], sizeof(int), cudaMemcpyHostToDevice);
    }

    printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_candidate);
    free(h_a);
    free(h_d);
    return 0;
}

