#include <cuda_runtime.h>
#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;

__global__ void popcountKernel(const uint64_t *d, int N, int L, unsigned long long totalPairs, unsigned long long *result) {
    unsigned long long localSum = 0;
    unsigned long long idx = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long stride = gridDim.x * blockDim.x;
    unsigned long long totalWork = totalPairs * L;
    while (idx < totalWork) {
        // Determine which pair (i,j) and word index w this thread is working on.
        int pairIndex = idx / L;
        int w = idx % L;
        // Decode pairIndex into (i, j)
        int i = 0;
        int cum = 0;
        // The number of pairs for row i is (N-i-1)
        // Find i such that cum + (N-i-1) > pairIndex.
        while (true) {
            int cnt = N - i - 1;
            if (pairIndex < cum + cnt) break;
            cum += cnt;
            i++;
        }
        int j = pairIndex - cum + i + 1;
        // Compute the popcount of the XOR of the corresponding 64-bit integers.
        uint64_t val1 = d[(size_t)i * L + w];
        uint64_t val2 = d[(size_t)j * L + w];
        unsigned long long pop = __popcll(val1 ^ val2);
        localSum += pop;
        idx += stride;
    }
    atomicAdd(result, localSum);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, L;
    cin >> N >> L;
    size_t totalElem = (size_t)N * L;
    vector<uint64_t> host_d(totalElem);
    for (int i = 0; i < N; i++){
        for (int w = 0; w < L; w++){
            host_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    // Allocate device memory and copy host_d.
    uint64_t *dev_d;
    cudaMalloc((void**)&dev_d, totalElem * sizeof(uint64_t));
    cudaMemcpy(dev_d, host_d.data(), totalElem * sizeof(uint64_t), cudaMemcpyHostToDevice);

    // Calculate total number of pairs = N*(N-1)/2.
    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) / 2;

    // Allocate device memory for result and initialize to 0.
    unsigned long long *dev_result;
    cudaMalloc((void**)&dev_result, sizeof(unsigned long long));
    cudaMemset(dev_result, 0, sizeof(unsigned long long));

    // Launch kernel.
    int threadsPerBlock = 256;
    // Total work items: totalPairs * L.
    unsigned long long totalWork = totalPairs * (unsigned long long)L;
    int blocks = (totalWork + threadsPerBlock - 1) / threadsPerBlock;
    if(blocks > 65535) blocks = 65535; // Limit blocks if needed.
    popcountKernel<<<blocks, threadsPerBlock>>>(dev_d, N, L, totalPairs, dev_result);
    cudaDeviceSynchronize();

    // Copy result back to host.
    unsigned long long host_result = 0;
    cudaMemcpy(&host_result, dev_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);

    cout << host_result << "\n";

    cudaFree(dev_d);
    cudaFree(dev_result);
    return 0;
}

