#include <cuda_runtime.h>
#include <iostream>
#include <algorithm>
using namespace std;

#define THREADS_PER_BLOCK 256

__global__ void gen_a(int* a, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        // Use 64-bit multiplication to avoid overflow.
        long long t = (long long)i * 48271LL + ((long long)i >> 1) * 163LL + 7;
        a[i] = (int)(t % 100000);
    }
}

__global__ void init_d(int* d, int N) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        d[i] = 1;
    }
}

__global__ void compute_candidate(const int* a, const int* d, int i, int* candidate) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int j = idx; j < i; j += stride) {
        if(a[j] < a[i]) {
            int val = d[j] + 1;
            atomicMax(candidate, val);
        }
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));

    int blocks = (N + THREADS_PER_BLOCK - 1) / THREADS_PER_BLOCK;
    gen_a<<<blocks, THREADS_PER_BLOCK>>>(d_a, N);
    init_d<<<blocks, THREADS_PER_BLOCK>>>(d_d, N);
    cudaDeviceSynchronize();

    int best = 1;
    for(int i = 1; i < N; i++){
        int *d_cand;
        cudaMalloc(&d_cand, sizeof(int));
        cudaMemset(d_cand, 0, sizeof(int));

        int threads = THREADS_PER_BLOCK;
        int grid = (i + threads - 1) / threads;
        if(grid < 1) grid = 1;
        compute_candidate<<<grid, threads>>>(d_a, d_d, i, d_cand);
        cudaDeviceSynchronize();

        int candidate;
        cudaMemcpy(&candidate, d_cand, sizeof(int), cudaMemcpyDeviceToHost);
        cudaFree(d_cand);

        if(candidate == 0)
            candidate = 1;

        cudaMemcpy(d_d + i, &candidate, sizeof(int), cudaMemcpyHostToDevice);
        best = max(best, candidate);
    }

    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    return 0;
}

