#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <iomanip>
#include <cuda_runtime.h>

__global__ void updateKernel(const double* A, double* B, int H, int W, double a) {
    int i = blockIdx.y * blockDim.y + threadIdx.y;
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(i >= 1 && i < H-1 && j >= 1 && j < W-1) {
        int id = i * W + j;
        int id_up = (i-1) * W + j;
        int id_down = (i+1) * W + j;
        int id_left = i * W + (j-1);
        int id_right = i * W + (j+1);
        B[id] = A[id] + a * (A[id_up] + A[id_down] + A[id_left] + A[id_right] - 4.0 * A[id]);
    }
}

int main(){
    int H, W, T;
    std::cin >> H >> W >> T;
    size_t size = H * W * sizeof(double);

    double* h_A = new double[H*W];
    for (int i = 0; i < H; i++){
        for (int j = 0; j < W; j++){
            h_A[i * W + j] = i * 0.1 + j * 0.2;
        }
    }

    double *d_A, *d_B;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);

    double a = 0.125;
    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((W + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (H + threadsPerBlock.y - 1) / threadsPerBlock.y);

    for(int t = 0; t < T; t++){
        updateKernel<<<numBlocks, threadsPerBlock>>>(d_A, d_B, H, W, a);
        cudaDeviceSynchronize();
        double* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A, d_A, size, cudaMemcpyDeviceToHost);

    double s = 0;
    for (int i = 0; i < H*W; i++){
        s += h_A[i];
    }
    std::cout << std::fixed << std::setprecision(6) << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    delete[] h_A;
    return 0;
}

