        int w = idx % L;
        d[idx] = (uint64_t)( (unsigned int)i * 1315423911u + (unsigned int)w * 2654435761u );
    }
}

__global__ void popcountKernel(const uint64_t* d, int N, int L, unsigned long long* result) {
    // total iterations = (N*(N-1)/2)*L
    size_t totalPairs = (size_t)N * (N - 1) / 2;
    size_t totalIt = totalPairs * L;
    size_t tid = blockDim.x * blockIdx.x + threadIdx.x;
    if (tid >= totalIt)
        return;
    size_t pairIndex = tid / L;
    int w = tid % L;
    // Map pairIndex to (i, j)
    // Solve for i using: i = floor((2N - 1 - sqrt((2N - 1)^2 - 8*pairIndex)) / 2)
    double temp = (double)(2 * N - 1);
    double disc = temp * temp - 8.0 * pairIndex;
    int i = (int)floor((temp - sqrt(disc)) / 2.0);
    size_t base = (size_t)i * N - (size_t)i * (i + 1) / 2;
    int j = i + 1 + (int)(pairIndex - base);
    uint64_t a = d[(size_t)i * L + w];
    uint64_t b = d[(size_t)j * L + w];
    unsigned int popc = __popcll(a ^ b);
    atomicAdd(result, (unsigned long long)popc);
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L) != 2) {
        return 1;
    }
    size_t dSize = (size_t)N * L * sizeof(uint64_t);
    uint64_t* d_d;
    CUDA_CHECK(cudaMalloc((void**)&d_d, dSize));

    // Launch init kernel
    size_t totalElements = (size_t)N * L;
    int blockSize = 256;
    int gridSize = (totalElements + blockSize - 1) / blockSize;
    initKernel<<<gridSize, blockSize>>>(d_d, N, L);
    CUDA_CHECK(cudaGetLastError());

    // Allocate result on device and initialize to 0
    unsigned long long* d_result;
    CUDA_CHECK(cudaMalloc((void**)&d_result, sizeof(unsigned long long)));
    CUDA_CHECK(cudaMemset(d_result, 0, sizeof(unsigned long long)));

    // Launch popcount kernel
    size_t totalPairs = (size_t)N * (N - 1) / 2;
    size_t totalIt = totalPairs * L;
    gridSize = (totalIt + blockSize - 1) / blockSize;
    popcountKernel<<<gridSize, blockSize>>>(d_d, N, L, d_result);
    CUDA_CHECK(cudaGetLastError());

    // Copy result back to host
    unsigned long long s = 0;
    CUDA_CHECK(cudaMemcpy(&s, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost));

    printf("%llu\n", s);

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

