__global__ void stencil_update(const double *A, double *B, int H, int W, double a) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i < H - 1 && j < W - 1) {
        int idx = i * W + j;
        B[idx] = A[idx] + a * (A[(i-1)*W + j] + A[(i+1)*W + j] +
                                A[i*W + (j-1)] + A[i*W + (j+1)] - 4 * A[idx]);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    size_t size = H * W * sizeof(double);
    vector<double> host_A(H * W), host_B(H * W);

    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            host_A[i * W + j] = i * 0.1 + j * 0.2;
        }
    }

    double a = 0.125;
    double *d_A, *d_B;
    cudaMalloc((void**)&d_A, size);
    cudaMalloc((void**)&d_B, size);
    cudaMemcpy(d_A, host_A.data(), size, cudaMemcpyHostToDevice);

    dim3 blockDim(16, 16);
    dim3 gridDim((W - 2 + blockDim.x - 1) / blockDim.x, (H - 2 + blockDim.y - 1) / blockDim.y);

    for (int t = 0; t < T; t++){
        stencil_update<<<gridDim, blockDim>>>(d_A, d_B, H, W, a);
        cudaDeviceSynchronize();
        double* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(host_A.data(), d_A, size, cudaMemcpyDeviceToHost);

    double s = 0;
    for(auto v : host_A)
        s += v;

    cout.setf(ios::fixed);
    cout << setprecision(6) << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

