#include <cstdio>
#include <cstdlib>
#include <cuda_runtime.h>
#include <algorithm>

#define THREADS_PER_BLOCK 256

// Kernel to update d[i] in parallel using j from 0 to i-1
__global__ void update_kernel(int i, const int *a, int *d) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = gridDim.x * blockDim.x;
    // Loop over j indices with stride
    for (int j = idx; j < i; j += stride) {
        // If a[j] < a[i], consider candidate d[j] + 1
        if(a[j] < a[i]) {
            int candidate = d[j] + 1;
            // Atomic max update on d[i]
            atomicMax(&d[i], candidate);
        }
    }
}

// Kernel for reduction to find maximum value in array 'd'
__global__ void reduce_max(const int *d_in, int *d_out, int N) {
    extern __shared__ int sdata[];
    unsigned int tid = threadIdx.x;
    unsigned int i = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    int myMax = 0;
    if(i < N)
        myMax = d_in[i];
    if(i + blockDim.x < N) {
        myMax = max(myMax, d_in[i + blockDim.x]);
    }
    sdata[tid] = myMax;
    __syncthreads();

    for (unsigned int s = blockDim.x/2; s > 0; s >>= 1) {
        if(tid < s) {
            sdata[tid] = max(sdata[tid], sdata[tid+s]);
        }
        __syncthreads();
    }
    if(tid == 0)
        d_out[blockIdx.x] = sdata[0];
}

int main(){
    int N;
    std::scanf("%d", &N);

    // Host arrays
    int *h_a = new int[N];
    int *h_d = new int[N];

    // Initialize arrays similar to original code.
    for (int i = 0; i < N; i++){
        h_a[i] = (int)((i * 48271LL + (i >> 1) * 163LL + 7) % 100000);
        h_d[i] = 1;
    }

    // Device arrays
    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));

    // Copy data to device
    cudaMemcpy(d_a, h_a, N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d, N * sizeof(int), cudaMemcpyHostToDevice);

    // For each i, update d[i] by checking all previous j values in parallel.
    for (int i = 1; i < N; i++){
        int threads = THREADS_PER_BLOCK;
        int blocks = (i + threads - 1) / threads;
        update_kernel<<<blocks, threads>>>(i, d_a, d_d);
        cudaDeviceSynchronize();
    }

    // Reduction to compute the maximum value in d array.
    int currentSize = N;
    int *d_in = d_d;
    int *d_out;
    cudaMalloc((void**)&d_out, ((currentSize+ (THREADS_PER_BLOCK*2 -1))/(THREADS_PER_BLOCK*2)) * sizeof(int));

    while (currentSize > 1) {
        int blocks = (currentSize + THREADS_PER_BLOCK*2 - 1) / (THREADS_PER_BLOCK*2);
        int sharedMemSize = THREADS_PER_BLOCK * sizeof(int);
        reduce_max<<<blocks, THREADS_PER_BLOCK, sharedMemSize>>>(d_in, d_out, currentSize);
        cudaDeviceSynchronize();
        currentSize = blocks;
        d_in = d_out;
    }

    int best;
    cudaMemcpy(&best, d_out, sizeof(int), cudaMemcpyDeviceToHost);
    std::printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_out);
    delete[] h_a;
    delete[] h_d;
    return 0;
}

