#include <cstdio>
#include <cuda_runtime.h>
#include <algorithm>

// Kernel to initialize the arrays a and d.
__global__ void init_arrays(int *a, int *d, int N) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < N) {
        long long val = (long long)idx * 48271LL + ((long long)idx >> 1) * 163LL + 7;
        a[idx] = (int)(val % 100000LL);
        d[idx] = 1;
    }
}

// Kernel to update dp value at index i.
__global__ void update_dp(const int *a, int *d, int i) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x + blockIdx.x * blockDim.x;
    int stride = gridDim.x * blockDim.x;
    int local_max = 1;
    for (int j = tid; j < i; j += stride) {
        if (a[j] < a[i]) {
            int candidate = d[j] + 1;
            if (candidate > local_max)
                local_max = candidate;
        }
    }
    int ltid = threadIdx.x;
    sdata[ltid] = local_max;
    __syncthreads();
    for (int s = blockDim.x/2; s > 0; s /= 2) {
        if (ltid < s)
            sdata[ltid] = max(sdata[ltid], sdata[ltid+s]);
        __syncthreads();
    }
    if (ltid == 0)
        atomicMax(&d[i], sdata[0]);
}

// Kernel to reduce the d array and compute the global maximum.
__global__ void reduce_max(const int *d, int *result, int N) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int local = (i < N) ? d[i] : 0;
    sdata[tid] = local;
    __syncthreads();
    for (int s = blockDim.x/2; s > 0; s /= 2) {
        if (tid < s)
            sdata[tid] = max(sdata[tid], sdata[tid+s]);
        __syncthreads();
    }
    if (tid == 0)
        atomicMax(result, sdata[0]);
}

int main(){
    int N;
    scanf("%d", &N);
    int *dev_a, *dev_d;
    cudaMalloc(&dev_a, N * sizeof(int));
    cudaMalloc(&dev_d, N * sizeof(int));

    int blockSize = 256;
    int gridSize = (N + blockSize - 1) / blockSize;
    init_arrays<<<gridSize, blockSize>>>(dev_a, dev_d, N);
    cudaDeviceSynchronize();

    for (int i = 1; i < N; i++){
        int threads = (i < blockSize) ? i : blockSize;
        int blocks = (i + threads - 1) / threads;
        update_dp<<<blocks, threads, threads * sizeof(int)>>>(dev_a, dev_d, i);
        cudaDeviceSynchronize();
    }

    int *dev_result;
    cudaMalloc(&dev_result, sizeof(int));
    cudaMemset(dev_result, 0, sizeof(int));
    gridSize = (N + blockSize - 1) / blockSize;
    reduce_max<<<gridSize, blockSize, blockSize * sizeof(int)>>>(dev_d, dev_result, N);
    cudaDeviceSynchronize();

    int best;
    cudaMemcpy(&best, dev_result, sizeof(int), cudaMemcpyDeviceToHost);
    printf("%d\n", best);

    cudaFree(dev_a);
    cudaFree(dev_d);
    cudaFree(dev_result);
    return 0;
}

