#include <cstdio>
#include <cuda_runtime.h>
#include <algorithm>
using namespace std;

__global__ void updateKernel(int i, const int *a, const int *d, int *d_new) {
    int j = blockIdx.x * blockDim.x + threadIdx.x;
    if(j < i) {
        if(a[j] < a[i]) {
            int candidate = d[j] + 1;
            atomicMax(&d_new[i], candidate);
        }
    }
}

__global__ void initKernel(int N, int *a) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        // Compute a[i] = (i*48271LL + (i>>1)*163LL + 7) % 100000
        long long v = (long long)i * 48271LL + ((long long)i >> 1) * 163LL + 7;
        a[i] = (int)(v % 100000);
    }
}

int main(){
    int N;
    scanf("%d", &N);

    // Allocate host memory for d
    int* h_d = new int[N];

    // Allocate device memory
    int *d_a, *d_d;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));

    // Initialize array 'a' on device
    int blockSize = 256;
    int numBlocks = (N + blockSize - 1) / blockSize;
    initKernel<<<numBlocks, blockSize>>>(N, d_a);
    cudaDeviceSynchronize();

    // Initialize d on device to 1
    int *h_init = new int[N];
    for(int i = 0; i < N; i++) h_init[i] = 1;
    cudaMemcpy(d_d, h_init, N * sizeof(int), cudaMemcpyHostToDevice);
    delete [] h_init;

    // For each i, update d[i] using j from 0 to i-1 in parallel.
    for (int i = 0; i < N; i++){
        int threads = 256;
        int blocks = (i + threads - 1) / threads;
        if(blocks > 0)
            updateKernel<<<blocks, threads>>>(i, d_a, d_d, d_d);
        cudaDeviceSynchronize();
    }

    // Copy d back to host and compute best
    cudaMemcpy(h_d, d_d, N * sizeof(int), cudaMemcpyDeviceToHost);
    int best = 0;
    for(int i = 0; i < N; i++){
        best = max(best, h_d[i]);
    }
    printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    delete [] h_d;
    return 0;
}

