#include <cuda_runtime.h>
#include <iostream>
using namespace std;

#define MOD 1000000007
#define INIT_MOD 1009

// Kernel to initialize matrix A of size n x k: A[i*k + x] = (i + 3*x) % INIT_MOD
__global__ void initA(int *A, int n, int k) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = n * k;
    if(idx < total) {
        int i = idx / k;
        int x = idx % k;
        A[idx] = (i + 3 * x) % INIT_MOD;
    }
}

// Kernel to initialize matrix B of size k x m: B[x*m + j] = (x + 7*j) % INIT_MOD
__global__ void initB(int *B, int k, int m) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = k * m;
    if(idx < total) {
        int x = idx / m;
        int j = idx % m;
        B[idx] = (x + 7 * j) % INIT_MOD;
    }
}

// Kernel for matrix multiplication: C[i*m+j] = sum_{x=0}^{k-1} A[i*k+x]*B[x*m+j] mod MOD
__global__ void matMul(const int *A, const int *B, int *C, int n, int k, int m) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    if(row < n && col < m) {
        long long sum = 0;
        for (int x = 0; x < k; x++) {
            sum = (sum + 1LL * A[row * k + x] * B[x * m + col]) % MOD;
        }
        C[row * m + col] = (int)sum;
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, m;
    cin >> n >> k >> m;

    size_t sizeA = n * k * sizeof(int);
    size_t sizeB = k * m * sizeof(int);
    size_t sizeC = n * m * sizeof(int);

    int *d_A, *d_B, *d_C;
    cudaMalloc(&d_A, sizeA);
    cudaMalloc(&d_B, sizeB);
    cudaMalloc(&d_C, sizeC);

    // Initialize matrices A and B
    int threads = 256;
    int blocksA = (n*k + threads - 1) / threads;
    initA<<<blocksA, threads>>>(d_A, n, k);
    int blocksB = (k*m + threads - 1) / threads;
    initB<<<blocksB, threads>>>(d_B, k, m);

    // Initialize matrix C to 0
    cudaMemset(d_C, 0, sizeC);

    // Launch matrix multiplication kernel
    dim3 blockDim(16, 16);
    dim3 gridDim((m + blockDim.x - 1) / blockDim.x, (n + blockDim.y - 1) / blockDim.y);
    matMul<<<gridDim, blockDim>>>(d_A, d_B, d_C, n, k, m);

    // Copy result C back to host and compute final sum
    int *h_C = new int[n * m];
    cudaMemcpy(h_C, d_C, sizeC, cudaMemcpyDeviceToHost);

    long long s = 0;
    for (int i = 0; i < n * m; i++){
        s = (s + h_C[i]) % MOD;
    }
    cout << s << "\n";

    // Free memory
    delete[] h_C;
    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);

    return 0;
}

