#include <iostream>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void compute_dp(int i, const int* a, int* d) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    int local_best = 1;
    for (int j = idx; j < i; j += stride) {
        if (a[j] < a[i]) {
            int candidate = d[j] + 1;
            if (candidate > local_best)
                local_best = candidate;
        }
    }
    atomicMax(&d[i], local_best);
}

__global__ void compute_best(const int* d, int N, int* best) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    int val = (idx < N) ? d[idx] : 0;
    sdata[tid] = val;
    __syncthreads();
    for (unsigned int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (tid < s) {
            if (sdata[tid + s] > sdata[tid])
                sdata[tid] = sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0)
        atomicMax(best, sdata[0]);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> h_a(N), h_d(N, 1);
    for (int i = 0; i < N; i++){
        h_a[i] = (int)((i * 48271LL + (i >> 1) * 163LL + 7) % 100000);
    }

    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));

    cudaMemcpy(d_a, h_a.data(), N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    const int threads = 256;
    for (int i = 1; i < N; i++){
        // Reset d[i] to 1 before computing
        int one = 1;
        cudaMemcpy(d_d + i, &one, sizeof(int), cudaMemcpyHostToDevice);
        int blocks = (i + threads - 1) / threads;
        compute_dp<<<blocks, threads>>>(i, d_a, d_d);
        cudaDeviceSynchronize();
    }

    int *d_best;
    cudaMalloc((void**)&d_best, sizeof(int));
    cudaMemset(d_best, 0, sizeof(int));

    int blocksForBest = (N + threads - 1) / threads;
    compute_best<<<blocksForBest, threads, threads * sizeof(int)>>>(d_d, N, d_best);
    cudaDeviceSynchronize();

    int best;
    cudaMemcpy(&best, d_best, sizeof(int), cudaMemcpyDeviceToHost);
    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_best);
    return 0;
}

