__global__ void simulateStep(const uint8_t *A, uint8_t *B, int H, int W) {
    int r = blockIdx.y * blockDim.y + threadIdx.y + 1;
    int c = blockIdx.x * blockDim.x + threadIdx.x + 1;
    if(r < H - 1 && c < W - 1) {
        int idx = r * W + c;
        int count =  A[(r-1)*W + (c-1)] + A[(r-1)*W + c] + A[(r-1)*W + (c+1)]
                   + A[r*W + (c-1)]                     + A[r*W + (c+1)]
                   + A[(r+1)*W + (c-1)] + A[(r+1)*W + c] + A[(r+1)*W + (c+1)];
        uint8_t cell = A[idx];
        if(cell)
            B[idx] = (count == 2 || count == 3) ? 1 : 0;
        else
            B[idx] = (count == 3) ? 1 : 0;
    }
}

