#include <iostream>
#include <iomanip>
#include <vector>
#include <cuda_runtime.h>
using namespace std;

__global__ void stencilKernel(const double *A, double *B, int H, int W, double a) {
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1;
    if (i < H - 1 && j < W - 1) {
        int idx = i * W + j;
        int idx_up = (i - 1) * W + j;
        int idx_down = (i + 1) * W + j;
        int idx_left = i * W + (j - 1);
        int idx_right = i * W + (j + 1);
        B[idx] = A[idx] + a * (A[idx_up] + A[idx_down] + A[idx_left] + A[idx_right] - 4 * A[idx]);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W, T;
    cin >> H >> W >> T;
    size_t size = H * W * sizeof(double);
    vector<double> h_A(H * W), h_B(H * W);
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            h_A[i * W + j] = i * 0.1 + j * 0.2;

    double a = 0.125;
    double *d_A, *d_B;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMemcpy(d_A, h_A.data(), size, cudaMemcpyHostToDevice);

    dim3 threadsPerBlock(16, 16);
    dim3 numBlocks((W - 2 + threadsPerBlock.x - 1) / threadsPerBlock.x,
                   (H - 2 + threadsPerBlock.y - 1) / threadsPerBlock.y);

    for (int t = 0; t < T; t++) {
        stencilKernel<<<numBlocks, threadsPerBlock>>>(d_A, d_B, H, W, a);
        cudaDeviceSynchronize();
        double* temp = d_A;
        d_A = d_B;
        d_B = temp;
    }

    cudaMemcpy(h_A.data(), d_A, size, cudaMemcpyDeviceToHost);

    double s = 0;
    for (double v : h_A) s += v;
    cout << fixed << setprecision(6) << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

