__global__ void pairSumKernel(const int *a, int N, unsigned long long int *d_sum) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < N) {
        unsigned long long int local = 0;
        for (int j = i + 1; j < N; j++) {
            int diff = a[i] - a[j];
            if(diff < 0) diff = -diff;
            local += diff;
        }
        atomicAdd(d_sum, local);
    }
}

int main(){
