    unsigned long long int *d_sum;
    cudaMalloc(&d_sum, sizeof(unsigned long long int));
    cudaMemset(d_sum, 0, sizeof(unsigned long long int));

    int blockSize = 256;
    int numBlocks = (N + blockSize - 1) / blockSize;
