#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cmath>

__global__ void initKernel(uint64_t* d, int N, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * L;
    if (idx < total) {
        int i = idx / L;
        int w = idx % L;
        d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void popcountKernel(const uint64_t* d, int N, int L, unsigned long long* result) {
    // Total pairs = N*(N-1)/2
    unsigned long long tid = blockIdx.x * blockDim.x + threadIdx.x;
    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) >> 1;
    if(tid >= totalPairs) return;

    // Decode tid into (i, j)
    // Let prefix(i) = i*N - i*(i+1)/2, then find smallest i such that prefix(i+1) > tid.
    // Use closed form formula: i = floor((2*N - 1 - sqrt((2*N - 1)*(2*N - 1) - 8*tid)) / 2)
    int i = (int)floor((2.0 * N - 1.0 - sqrt((2.0 * N - 1.0) * (2.0 * N - 1.0) - 8.0 * tid)) / 2.0);
    unsigned long long prefix = (unsigned long long)i * N - ((unsigned long long)i * (i + 1)) / 2;
    int j = (int)(tid - prefix + i + 1);

    unsigned long long localSum = 0;
    for (int w = 0; w < L; w++) {
        uint64_t a = d[(size_t)i * L + w];
        uint64_t b = d[(size_t)j * L + w];
        localSum += __popcll(a ^ b);
    }
    atomicAdd(result, localSum);
}

int main(){
    int N, L;
    if(scanf("%d %d",&N,&L)!=2) return 1;
    size_t numElements = (size_t)N * L;
    size_t dSize = numElements * sizeof(uint64_t);

    uint64_t* d_d;
    cudaMalloc(&d_d, dSize);

    int threadsPerBlock = 256;
    int blocksInit = (numElements + threadsPerBlock - 1) / threadsPerBlock;
    initKernel<<<blocksInit, threadsPerBlock>>>(d_d, N, L);

    unsigned long long* d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    unsigned long long totalPairs = ((unsigned long long)N * (N - 1)) >> 1;
    int blocksPop = (totalPairs + threadsPerBlock - 1) / threadsPerBlock;
    popcountKernel<<<blocksPop, threadsPerBlock>>>(d_d, N, L, d_result);

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);

    printf("%llu\n", h_result);

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

