#include <iostream>
#include <cstdint>
#include <cuda_runtime.h>
#include <thrust/device_ptr.h>
#include <thrust/reduce.h>
using namespace std;

__global__ void initKernel(uint8_t *A, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int N = H * W;
    if(idx >= N) return;
    int i = idx / W;
    int j = idx % W;
    A[idx] = ((i * 131u + j * 57u + 13u) ^ ((i << 3) + j)) & 1;
}

__global__ void updateKernel(const uint8_t *A, uint8_t *B, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner = (H - 2) * (W - 2);
    if(idx >= inner) return;
    int row = idx / (W - 2) + 1;
    int col = idx % (W - 2) + 1;
    int center = row * W + col;
    int cnt = 0;
    cnt += A[(row - 1) * W + (col - 1)];
    cnt += A[(row - 1) * W + col];
    cnt += A[(row - 1) * W + (col + 1)];
    cnt += A[row * W + (col - 1)];
    cnt += A[row * W + (col + 1)];
    cnt += A[(row + 1) * W + (col - 1)];
    cnt += A[(row + 1) * W + col];
    cnt += A[(row + 1) * W + (col + 1)];
    uint8_t state = A[center];
    if(state)
        B[center] = (cnt == 2 || cnt == 3) ? 1 : 0;
    else
        B[center] = (cnt == 3) ? 1 : 0;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, T;
    cin >> H >> W >> T;
    int size = H * W;
    uint8_t *d_A, *d_B;
    cudaMalloc(&d_A, size * sizeof(uint8_t));
    cudaMalloc(&d_B, size * sizeof(uint8_t));
    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;
    initKernel<<<gridSize, blockSize>>>(d_A, H, W);
    cudaDeviceSynchronize();
    int innerSize = (H - 2) * (W - 2);
    int gridSizeInner = (innerSize + blockSize - 1) / blockSize;
    for(int t = 0; t < T; t++){
        updateKernel<<<gridSizeInner, blockSize>>>(d_A, d_B, H, W);
        cudaDeviceSynchronize();
        uint8_t *temp = d_A;
        d_A = d_B;
        d_B = temp;
    }
    thrust::device_ptr<uint8_t> dev_ptr(d_A);
    long long s = thrust::reduce(dev_ptr, dev_ptr + size, 0LL, thrust::plus<long long>());
    cout << s << "\n";
    cudaFree(d_A);
    cudaFree(d_B);
    return 0;
}

