#include <iostream>
#include <vector>
#include <algorithm>
#include <cuda_runtime.h>
using namespace std;

__global__ void computeDP(int current, const int* a, const int* d, int* result) {
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int local_max = 0;
    for (int j = idx; j < current; j += blockDim.x * gridDim.x) {
        if(a[j] < a[current]){
            int candidate = d[j] + 1;
            if(candidate > local_max)
                local_max = candidate;
        }
    }
    sdata[tid] = local_max;
    __syncthreads();
    for (int stride = blockDim.x/2; stride > 0; stride /= 2) {
        if(tid < stride)
            sdata[tid] = max(sdata[tid], sdata[tid + stride]);
        __syncthreads();
    }
    if(tid == 0){
        atomicMax(result, sdata[0]);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int> a(N), d(N, 1);
    for (int i = 0; i < N; i++){
        a[i] = (int)(((long long)i * 48271LL + ((unsigned int)i >> 1) * 163LL + 7) % 100000);
    }

    int best = 0;

    int *d_a, *d_d, *d_result;
    cudaMalloc(&d_a, N * sizeof(int));
    cudaMalloc(&d_d, N * sizeof(int));
    cudaMalloc(&d_result, sizeof(int));

    cudaMemcpy(d_a, a.data(), N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, d.data(), N * sizeof(int), cudaMemcpyHostToDevice);

    int threads = 256;
    for (int i = 0; i < N; i++){
        if(i == 0){
            best = 1;
            continue;
        }
        int init = 1;
        cudaMemcpy(d_result, &init, sizeof(int), cudaMemcpyHostToDevice);
        int blocks = (i + threads - 1) / threads;
        computeDP<<<blocks, threads, threads * sizeof(int)>>>(i, d_a, d_d, d_result);
        int cand;
        cudaMemcpy(&cand, d_result, sizeof(int), cudaMemcpyDeviceToHost);
        int curr_val = (cand < 1) ? 1 : cand;
        cudaMemcpy(&d_d[i], &curr_val, sizeof(int), cudaMemcpyHostToDevice);
        if(curr_val > best)
            best = curr_val;
    }

    cout << best << "\n";

    cudaFree(d_a);
    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

