#include <cstdio>
#include <cstdint>
#include <cuda_runtime.h>
#include <inttypes.h>

__global__ void init_d(uint64_t *d, int N, int L) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * L;
    if (idx < total) {
        int i = idx / L;
        int w = idx % L;
        d[idx] = (uint64_t)(i * 1315423911u + w * 2654435761u);
    }
}

__global__ void compute_popcount(uint64_t *d, int N, int L, unsigned long long *result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && j < N && j > i) {
        unsigned long long local_sum = 0;
        for (int w = 0; w < L; w++) {
            uint64_t val = d[(size_t)i * L + w] ^ d[(size_t)j * L + w];
            local_sum += __popcll(val);
        }
        atomicAdd(result, local_sum);
    }
}

int main(){
    int N, L;
    scanf("%d %d", &N, &L);

    size_t size_d = (size_t)N * L * sizeof(uint64_t);
    uint64_t *d_d;
    cudaMalloc(&d_d, size_d);

    int totalElements = N * L;
    int threadsPerBlock = 256;
    int blocksInit = (totalElements + threadsPerBlock - 1) / threadsPerBlock;
    init_d<<<blocksInit, threadsPerBlock>>>(d_d, N, L);
    cudaDeviceSynchronize();

    unsigned long long *d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemset(d_result, 0, sizeof(unsigned long long));

    dim3 threads(16, 16);
    dim3 blocks((N + threads.x - 1) / threads.x, (N + threads.y - 1) / threads.y);
    compute_popcount<<<blocks, threads>>>(d_d, N, L, d_result);
    cudaDeviceSynchronize();

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    printf("%llu\n", h_result);

    cudaFree(d_d);
    cudaFree(d_result);
    return 0;
}

