#include <cuda_runtime.h>
#include <cstdio>
#include <cstdint>
#include <cstdlib>

__global__
void compute_popcounts(const uint64_t* d, int N, int L, unsigned long long* result) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int j = blockIdx.y * blockDim.y + threadIdx.y;
    if(i < N && j < N && j > i) {
        unsigned long long local_sum = 0;
        for (int w = 0; w < L; w++) {
            uint64_t a = d[(size_t)i * L + w];
            uint64_t b = d[(size_t)j * L + w];
            local_sum += __popcll(a ^ b);
        }
        atomicAdd(result, local_sum);
    }
}

int main(){
    int N, L;
    if(scanf("%d %d", &N, &L)!=2) {
        return 1;
    }
    size_t size = (size_t)N * L;
    uint64_t* h_d = (uint64_t*)malloc(size * sizeof(uint64_t));
    for (int i = 0; i < N; i++) {
        for (int w = 0; w < L; w++) {
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    // Allocate device memory
    uint64_t* d_d;
    cudaMalloc(&d_d, size * sizeof(uint64_t));
    cudaMemcpy(d_d, h_d, size * sizeof(uint64_t), cudaMemcpyHostToDevice);

    unsigned long long h_result = 0;
    unsigned long long* d_result;
    cudaMalloc(&d_result, sizeof(unsigned long long));
    cudaMemcpy(d_result, &h_result, sizeof(unsigned long long), cudaMemcpyHostToDevice);

    // Setup grid and block dimensions
    dim3 blockDim(16, 16);
    dim3 gridDim((N + blockDim.x - 1) / blockDim.x, (N + blockDim.y - 1) / blockDim.y);

    compute_popcounts<<<gridDim, blockDim>>>(d_d, N, L, d_result);
    cudaDeviceSynchronize();

    cudaMemcpy(&h_result, d_result, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    printf("%llu\n", h_result);

    cudaFree(d_d);
    cudaFree(d_result);
    free(h_d);
    return 0;
}

