#include <cuda_runtime.h>
#include <iostream>
#include <algorithm>
using namespace std;

#define CUDA_CHECK(call) \
    do { \
        cudaError_t err = call; \
        if(err != cudaSuccess) { \
            std::cerr << "CUDA error: " << cudaGetErrorString(err) << " at " << __FILE__ << ":" << __LINE__ << "\n"; \
            exit(EXIT_FAILURE); \
        } \
    } while(0)

__global__ void knapSackKernel(const int* dp_in, int* dp_out, int item_weight, int item_value, int W) {
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if(c <= W) {
        if(c >= item_weight)
            dp_out[c] = max(dp_in[c], dp_in[c - item_weight] + item_value);
        else
            dp_out[c] = dp_in[c];
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, W;
    cin >> N >> W;

    int *h_w = new int[N];
    int *h_v = new int[N];
    for (int i = 0; i < N; i++){
        h_w[i] = (i % 97) + 1;
        h_v[i] = (i * 31) % 1000 + 1;
    }

    // Allocate host DP array
    int sizeDP = (W + 1) * sizeof(int);
    int *h_dp = new int[W + 1];
    for(int i = 0; i <= W; i++){
        h_dp[i] = 0;
    }

    // Allocate device DP arrays
    int *d_dp_in, *d_dp_out;
    CUDA_CHECK(cudaMalloc((void**)&d_dp_in, sizeDP));
    CUDA_CHECK(cudaMalloc((void**)&d_dp_out, sizeDP));
    CUDA_CHECK(cudaMemcpy(d_dp_in, h_dp, sizeDP, cudaMemcpyHostToDevice));

    // CUDA kernel configuration
    int blockSize = 256;
    int gridSize = (W + 1 + blockSize - 1) / blockSize;

    for (int i = 0; i < N; i++){
        int item_weight = h_w[i];
        int item_value = h_v[i];
        knapSackKernel<<<gridSize, blockSize>>>(d_dp_in, d_dp_out, item_weight, item_value, W);
        CUDA_CHECK(cudaDeviceSynchronize());
        // Swap pointers for next iteration
        int *temp = d_dp_in;
        d_dp_in = d_dp_out;
        d_dp_out = temp;
    }

    // Copy result back. Depending on the parity, the final dp array will be in d_dp_in.
    CUDA_CHECK(cudaMemcpy(h_dp, d_dp_in, sizeDP, cudaMemcpyDeviceToHost));

    cout << h_dp[W] << "\n";

    // Cleanup
    delete [] h_dp;
    delete [] h_w;
    delete [] h_v;
    CUDA_CHECK(cudaFree(d_dp_in));
    CUDA_CHECK(cudaFree(d_dp_out));

    return 0;
}

