#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <iomanip>
#include <cuda_runtime.h>
using namespace std;

__global__
void evolve(int H, int W, double a, const double* A, double* B) {
    int j = blockIdx.x * blockDim.x + threadIdx.x + 1; 
    int i = blockIdx.y * blockDim.y + threadIdx.y + 1;
    if(i < H-1 && j < W-1) {
        int idx = i * W + j;
        B[idx] = A[idx] + a * ( A[(i-1)*W + j] + A[(i+1)*W + j] +
                                A[i*W + (j-1)] + A[i*W + (j+1)] -
                                4 * A[idx] );
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H,W,T;
    cin >> H >> W >> T;
    size_t size = H * W * sizeof(double);
    double *h_A = new double[H*W];
    double *h_B = new double[H*W];

    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            h_A[i*W+j] = i * 0.1 + j * 0.2;
        }
    }

    double a = 0.125;

    double *d_A, *d_B;
    cudaMalloc(&d_A, size);
    cudaMalloc(&d_B, size);
    cudaMemcpy(d_A, h_A, size, cudaMemcpyHostToDevice);

    dim3 blockDim(16, 16);
    int gridX = (W-2 + blockDim.x - 1) / blockDim.x;
    int gridY = (H-2 + blockDim.y - 1) / blockDim.y;
    dim3 gridDim(gridX, gridY);

    for (int t = 0; t < T; t++){
        evolve<<<gridDim, blockDim>>>(H, W, a, d_A, d_B);
        cudaDeviceSynchronize();
        double* tmp = d_A;
        d_A = d_B;
        d_B = tmp;
    }

    cudaMemcpy(h_A, d_A, size, cudaMemcpyDeviceToHost);

    double s = 0;
    for (int i = 0; i < H*W; i++){
        s += h_A[i];
    }
    cout.setf(ios::fixed);
    cout << setprecision(6) << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    delete[] h_A;
    delete[] h_B;
    return 0;
}

