#include <cuda_runtime.h>
#include <iostream>
#include <stdint.h>
using namespace std;

__global__ void popcountKernel(const uint64_t* d, int N, int L, unsigned long long* results, long long totalPairs) {
    long long id = blockIdx.x * blockDim.x + threadIdx.x;
    if(id >= totalPairs) return;
    int row = 0;
    long long tmp = id;
    // Map linear index to (row, col) pair where col = j (with j > row)
    while (tmp >= (N - row - 1)) {
        tmp -= (N - row - 1);
        row++;
    }
    int j = row + 1 + tmp;
    unsigned long long sum = 0;
    for(int w = 0; w < L; w++){
        sum += __popcll(d[(size_t)row * L + w] ^ d[(size_t)j * L + w]);
    }
    results[id] = sum;
}

__global__ void reductionKernel(const unsigned long long* input, unsigned long long* output, long long n) {
    extern __shared__ unsigned long long sdata[];
    long tid = threadIdx.x;
    long idx = blockIdx.x * blockDim.x * 2 + threadIdx.x;
    unsigned long long sum = 0;
    if(idx < n)
        sum = input[idx];
    if(idx + blockDim.x < n)
        sum += input[idx + blockDim.x];
    sdata[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if(tid < s)
            sdata[tid] += sdata[tid + s];
        __syncthreads();
    }
    if(tid == 0)
        output[blockIdx.x] = sdata[0];
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, L;
    cin >> N >> L;
    size_t totalElements = (size_t)N * L;
    uint64_t* h_d = new uint64_t[totalElements];
    for(int i = 0; i < N; i++){
        for(int w = 0; w < L; w++){
            h_d[(size_t)i * L + w] = (uint64_t)(i * 1315423911u + w * 2654435761u);
        }
    }

    uint64_t *d_d;
    cudaMalloc(&d_d, totalElements * sizeof(uint64_t));
    cudaMemcpy(d_d, h_d, totalElements * sizeof(uint64_t), cudaMemcpyHostToDevice);
    delete[] h_d;

    long long totalPairs = (long long)N * (N - 1) / 2;
    unsigned long long *d_results;
    cudaMalloc(&d_results, totalPairs * sizeof(unsigned long long));

    int threadsPerBlock = 256;
    int blocks = (totalPairs + threadsPerBlock - 1) / threadsPerBlock;
    popcountKernel<<<blocks, threadsPerBlock>>>(d_d, N, L, d_results, totalPairs);
    cudaDeviceSynchronize();

    unsigned long long *d_in = d_results;
    unsigned long long *d_out = nullptr;
    long long n = totalPairs;
    while(n > 1){
        int threads = 256;
        int blocks = (n + threads * 2 - 1) / (threads * 2);
        cudaMalloc(&d_out, blocks * sizeof(unsigned long long));
        reductionKernel<<<blocks, threads, threads * sizeof(unsigned long long)>>>(d_in, d_out, n);
        cudaDeviceSynchronize();
        cudaFree(d_in);
        d_in = d_out;
        n = blocks;
    }

    unsigned long long h_result;
    cudaMemcpy(&h_result, d_in, sizeof(unsigned long long), cudaMemcpyDeviceToHost);
    cout << h_result << "\n";

    cudaFree(d_in);
    cudaFree(d_d);
    return 0;
}

