#include <iostream>
#include <cuda_runtime.h>
#include <thrust/device_ptr.h>
#include <thrust/reduce.h>
using namespace std;

#define MOD 1000000007

__global__ void initA(int *A, int n, int k) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = n * k;
    if (idx < total) {
        int i = idx / k;
        int x = idx % k;
        A[idx] = (i + 3 * x) % 1009;
    }
}

__global__ void initB(int *B, int k, int m) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = k * m;
    if (idx < total) {
        int x = idx / m;
        int j = idx % m;
        B[idx] = (x + 7 * j) % 1009;
    }
}

__global__ void initC(int *C, int total) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < total) {
        C[idx] = 0;
    }
}

__global__ void matMul(const int *A, const int *B, int *C, int n, int k, int m) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = n * m;
    if (idx < total) {
        int i = idx / m;
        int j = idx % m;
        long long sum = 0;
        for (int x = 0; x < k; x++) {
            sum = (sum + (long long)A[i * k + x] * B[x * m + j]) % MOD;
        }
        C[idx] = sum;
    }
}

struct ModAdd {
    __host__ __device__
    long long operator()(long long a, long long b) const {
        long long s = a + b;
        return s >= MOD ? s - MOD : s;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, m;
    cin >> n >> k >> m;
    int sizeA = n * k;
    int sizeB = k * m;
    int sizeC = n * m;

    int *d_A, *d_B, *d_C;
    cudaMalloc((void**)&d_A, sizeA * sizeof(int));
    cudaMalloc((void**)&d_B, sizeB * sizeof(int));
    cudaMalloc((void**)&d_C, sizeC * sizeof(int));

    int blockSize = 256;
    int gridA = (sizeA + blockSize - 1) / blockSize;
    int gridB = (sizeB + blockSize - 1) / blockSize;
    int gridC = (sizeC + blockSize - 1) / blockSize;

    initA<<<gridA, blockSize>>>(d_A, n, k);
    initB<<<gridB, blockSize>>>(d_B, k, m);
    initC<<<gridC, blockSize>>>(d_C, sizeC);
    cudaDeviceSynchronize();

    int gridMat = (sizeC + blockSize - 1) / blockSize;
    matMul<<<gridMat, blockSize>>>(d_A, d_B, d_C, n, k, m);
    cudaDeviceSynchronize();

    thrust::device_ptr<int> dev_ptr(d_C);
    long long s = thrust::reduce(dev_ptr, dev_ptr + sizeC, 0LL, ModAdd());
    s %= MOD;

    cout << s << "\n";

    cudaFree(d_A);
    cudaFree(d_B);
    cudaFree(d_C);
    return 0;
}

