#include <cstdio>
#include <cstdlib>
#include <algorithm>
#include <cuda.h>
#include <cuda_runtime.h>

#define THREADS_PER_BLOCK 256

__global__ void compute_dp(int i, const int *a, int *d)
{
    extern __shared__ int sdata[];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + tid;
    int candidate = 1;
    if(idx < i){
        if(a[idx] < a[i]){
            candidate = d[idx] + 1;
        }
    }
    sdata[tid] = candidate;
    __syncthreads();

    // Parallel reduction in shared memory
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if(tid < s){
            int other = sdata[tid + s];
            if(other > sdata[tid])
                sdata[tid] = other;
        }
        __syncthreads();
    }
    if(tid == 0)
        atomicMax(&d[i], sdata[0]);
}

int main(){
    int N;
    if(scanf("%d",&N)!=1) return -1;

    int *h_a = (int*)malloc(N * sizeof(int));
    int *h_d = (int*)malloc(N * sizeof(int));

    for(int i = 0; i < N; i++){
        h_a[i] = (int)(((long long)i * 48271LL + (i >> 1) * 163LL + 7) % 100000);
        h_d[i] = 1;
    }

    int *d_a, *d_d;
    cudaMalloc((void**)&d_a, N * sizeof(int));
    cudaMalloc((void**)&d_d, N * sizeof(int));
    cudaMemcpy(d_a, h_a, N * sizeof(int), cudaMemcpyHostToDevice);
    cudaMemcpy(d_d, h_d, N * sizeof(int), cudaMemcpyHostToDevice);

    for (int i = 0; i < N; i++){
        if(i == 0) continue;
        int numThreads = (i < THREADS_PER_BLOCK) ? i : THREADS_PER_BLOCK;
        int numBlocks = (i + numThreads - 1) / numThreads;
        compute_dp<<<numBlocks, numThreads, numThreads * sizeof(int)>>>(i, d_a, d_d);
        cudaDeviceSynchronize();
    }

    cudaMemcpy(h_d, d_d, N * sizeof(int), cudaMemcpyDeviceToHost);

    int best = 0;
    for (int i = 0; i < N; i++){
        best = std::max(best, h_d[i]);
    }
    printf("%d\n", best);

    cudaFree(d_a);
    cudaFree(d_d);
    free(h_a);
    free(h_d);
    return 0;
}
